S = []  # (stufe_id, titel, untertitel, rows)
# row: (nr, paket, heute, loesung, wer, pushes, status)
S.append(("s0","Stufe 0 · Sicherheit","Kontoübernahme und Rechtsrisiko – vor allem anderen",[
("164b","Zwei-Faktor im Team","Mitarbeiter ohne Handy oder Notfall-Code konnten nur über das Supabase-Dashboard wieder hinein; niemand im Betrieb konnte helfen.","Chef und eine Vertretung setzen die Zwei-Faktor-Anmeldung zurück, der Betreiber hat eine eigene Tür im Command Center, Hilfe-Anfrage per Glocke.","G","1","live"),
("169","Konto-Schutz","Die Mitarbeiter-Einladung übernahm fremde Konten per E-Mail. Ein Chef konnte über die Login-Verknüpfung das Passwort fremder Personen setzen und ihre Zwei-Faktor löschen. Jeder Nutzer konnte sich selbst zum Admin machen. 24 Datenbank-Funktionen waren ohne Anmeldung aufrufbar.","Bestehende Konten werden nie übernommen, jedes Zurücksetzen prüft das Ziel-Konto, die Verknüpfung setzt nur noch der Server, Rolle und Tarif sind gesperrt, Funktionen nur noch mit Anmeldung bzw. nur für den Server.","G","1","live"),
("170","Admin-Doppelschloss","8 Admin-Routen prüften nur die Rolle „admin“. Der Website-Modus ließ ohne gesetzte Variable jeden Angemeldeten durch. Zwei Routen hatten ein eigenes Schloss ohne Zwei-Faktor.","Alle Admin-Wege prüfen Rolle, Betreiber-Kennung und Zwei-Faktor über eine zentrale Stelle; ein Test verhindert neue Lücken.","C","1","live"),
("173","Werbe-Mails rechtssicher","Autoresponder schickt Werbeserien an frei eingetippte Adressen ohne Einwilligung. Bewertungs-Bitten ohne Einwilligung und ohne Abmeldelink. Jede Website-Anfrage startet ungefragt eine Werbeserie. Termin-Nachfass ohne Abmeldelink, der Name aus dem Formular geht ungeschützt in die Mail (Phishing-Gefahr). Mails aus Abläufen kommen als „ARGONAUT OS“, Antworten landen bei info@. Abmeldung wirkt nur in einem Kanal. Newsletter prüft die Bestätigung nicht.","Werbung nur an bestätigte Einwilligungen, Abmeldelink und Widerspruchshinweis in jeder Werbe-Mail, eigenes Häkchen für die Dossier-Serie, Namen geschützt, Absender und Antwortadresse des Betriebs, eine Abmeldung stoppt alle Kanäle.","C","1","live"),
]))
S.append(("s1","Stufe 1 · Vor dem ersten weiteren Kunden","Mandantentrennung, Geld, KI-Regeln, Datenschutz, Testtag-Vorbereitung",[
("174","Mandanten-Lücken in der Datenbank","Ehemalige Mitarbeiter oder Fremde mit Kanal-Kennung können Team-Chat-Kanälen selbst beitreten und alles lesen. Ein Chef kann sich bezahlte Module selbst freischalten. Mitarbeiter können HR-Einträge bei einem fremden Betrieb anlegen. Chat-Absender lassen sich fälschen.","Beitritt nur im eigenen Betrieb, Modul-Freischaltung nur über den Betreiber, HR-Einträge immer beim eigenen Betrieb, Absender = angemeldete Person. SQL getrennt.","G","1","live"),
("175","Geld-Routen absichern","Rechnungs-, Mahnungs- und Auftragsbestätigungs-PDFs lassen sich ohne Login erzeugen. Die Kasse kann Lager auf fremde Artikel buchen. „Rechnung senden“ versendet auch für Mitarbeiter ohne Abrechnungsrecht. Ein Mitarbeiter kann ein ARGONAUT-Abo mit SEPA anlegen. „Rechnung neu berechnen“ prüft den Besitzer nicht.","Login-Pflicht für alle PDF-Routen, Artikel nur aus dem eigenen Betrieb, Senden nur mit Abrechnungsrecht, Abo nur durch den Chef, Besitzer-Prüfung in der Datenbank-Funktion.","G","1","live"),
("176","KI-Regeln einhalten","Die KI schätzt Marktpreise für Auftragspositionen (gegen die Grundregel). Die HR-Auswertung schickt Krankheitsmuster an die KI, der Dashboard-Chat die Namen Krankgemeldeter. Stapel-Aufträge fehlen im KI-Kostenprotokoll.","Platzhalter „Preis bitte ergänzen“, keine Krankheitsdaten an die KI (nur Anzahlen), Stapel-Kosten im Protokoll.","C","1","live"),
("177","Kündigungs-Sperre wirksam","Die Sperre für gekündigte Kunden liest eine Liste, in die nie jemand etwas einträgt. Gekündigte Kunden und ihre Mitarbeiter arbeiten weiter.","Sperre je Betrieb per Knopf in der Betriebs-Akte (mit Grund, jederzeit aufhebbar) – gilt für Chef, Mitarbeiter, Anmeldung und Schnittstellen. Automatisch ab Vertragsende, sobald die Stripe-Bestellstrecke steht.","G","1","live"),
("178","Datenschutzerklärung neu","Die Erklärung sagt „Anthropic anonymisiert“ und „Voyage entfernt Personenbezug“ – beides stimmt nicht. Resend, Ersatz-KI, PDF-Server, WhatsApp, Social-Schnittstellen, Messung und die Gesundheitsmodule fehlen.","Erklärung vollständig und richtig neu fassen, danach Anwalt; Baukasten-Vorlage für Kundenseiten mitziehen.","G","1","live"),
("179","Musterbetrieb XXL","Für den Testtag gibt es keinen Betrieb, in dem alle Module mit Daten gefüllt sind; jede Seite müsste von Hand befüllt werden.","Ein vollständiger Musterbetrieb mit Beispieldaten in allen Modulen, per Knopf anlegbar und wieder löschbar.","C","2","live"),
("180","Fachbeschreibung Elektriker","Das Dossier ist ein Werbetext; eine Beschreibung, was das System für eine Branche wirklich kann, fehlt.","8–12 Seiten für Laien, nur Gebautes, Vorgebautes als „in Vorbereitung“; danach Vorlage für alle Branchen.","C","0","live"),
("190","Zwei-Faktor-Pflicht je Betrieb","Pflicht für alle geht nur über eine Server-Variable für ganz ARGONAUT; der Inhaber kann sie für seinen Betrieb nicht selbst einschalten.","Schalter „Für alle Pflicht“ nur für den Inhaber (mit eigenem Code), Bestätigung mit Häkchen „Mitarbeiter informiert“ und „Betriebsrat einbezogen bzw. keiner vorhanden“, Nachweis wer/wann, 7 Tage Übergangsfrist, jederzeit abschaltbar.","G","1","live"),
("191","Cent-Rundung reparieren","Die Rundung rundete ab etwa 2 € halbe Cent ab: 0,5 × 8,79 € wurde 4,39 € statt 4,40 €, 19 % von 42,50 € wurden 8,07 € statt 8,08 € – gemessen bei 65.613 von 1 Mio. Beträgen und 604 von 40.000 Steuerbeträgen.","Eine zentrale Rundung ohne Gleitkomma-Fehler für Angebot, Rechnung, Kalkulator, Zahlung, Abo, SEPA, Mahnwesen, Finanzen und Gebühren; PDF und E-Rechnung zeigen alte Rechnungen centgenau wie verschickt (GoBD).","G","1","live"),
("192","Knopf-Abläufe und Glocke gezielter","Knopf-Abläufe drückt nur der Chef; Meldungen aus Abläufen gehen nur an den Chef oder an alle Mitarbeiter.","Je Ablauf Haken „Auch Mitarbeiter mit Schreibrecht dürfen starten“; Glocke zusätzlich an ausgewählte Personen oder eine Abteilung.","C","1","live"),
("193","KI-Modelle zentral nach Aufgabe","Welches KI-Modell eine Funktion nutzt, steht in jeder Datei einzeln; ein Modell-Wechsel heißt viele Stellen ändern.","Eine Zuordnung Aufgabe → Modell: günstiges schnelles Modell für interne Auswertungen, Zusammenfassungen und Hilfe; stärkeres Modell für Texte an Kunden. Im Ablauf-Baustein wählbar „intern“ oder „Kundentext“.","C","1","live"),
("194","Grundausstattung für alle","Viele Module für jeden Betrieb (Anfragen, Lager, Mahnwesen, Marketing, Bewertungen, Personal, Team-Chat …) lagen nur in einzelnen Branchen-Paketen oder hinter einem Betreiber-Schalter – für den Kunden sahen sie aus wie fehlend.","Alles Branchen-Neutrale gehört zum Kern (53 Module), Branchen-Pakete zeigen nur noch das Fachliche; Kalkulator ins Handwerk-Paket. SQL schaltet bei bestehenden Betrieben nur hinzu.","C","1","live"),
("195","Testzugang als Anfrage","„7 Tage kostenlos testen“ klang nach Sofortstart, obwohl kein Konto entsteht; die erste Test-Mail sagte „startklar“.","Knopf „Zugang anfordern“ mit Branche, Testseite in drei Schritten, 7 Tage ab Freischaltung; Martin schaltet jeden Zugang selbst frei.","C","1","live"),
("188","Voice Layer Stufe 1","Vorlesen nur mit der Browser-Stimme, klingt je Gerät anders und robotisch.","Deine geklonte Stimme über ElevenLabs, nur mit Login, Längen- und Tagesdeckel, Browser-Stimme bleibt Rückfall.","C","1","wartet auf Martin"),
]))
S.append(("s2","Stufe 2 · Bald","Rechte sauber ziehen, Lücken aus alten Modulen schließen",[
("181","Geld- und Personal-Seiten auf „Betrieb“","Auf 13 Seiten (Abo-Rechnungen, Eingangsbelege, Ausgaben, Reisekosten, Mitglieder, Personal, Provisionen, Nachkalkulation, Ernte-Zahlungen, Portal-Zugänge, Verträge, Fördervorhaben, Rückholung) speichern Mitarbeiter unter eigener Kennung – der Chef sieht diese Einträge nicht.","Speichern immer für den Betrieb, wie in Paket 165; SQL getrennt, weil es Mitarbeiter ohne Schreibrecht betrifft.","G","2","live"),
("182","Angebot-Link erst ab „versendet“","Ein Angebot im Entwurf ist per Link annehmbar, das Kundenportal zeigt Entwürfe, die Annahme speichert keinen Namen.","Link und Portal erst ab Status „versendet“, Annahme mit Name und Zeitpunkt.","G","1","live"),
("183","WhatsApp-Anmeldung mit Bestätigung","Eine Nummer ist nach dem Formular sofort aktiv; Dritte können fremde Nummern eintragen.","Nummer erst aktiv, wenn die Person per WhatsApp antwortet; Nachweis gespeichert.","C","1","live"),
("184","Dateien, Uploads, IBAN, Import","Einige Download-Wege vertrauen gespeicherten Pfaden – bei bekanntem Dateinamen fremde Datei abrufbar. Eine Tresenkraft lädt IBANs mit. Der Import erkennt Bank- und Werbe-Spalten nur am Namen. Speicher ohne feste Größen- und Typgrenzen, AU-Bescheinigungen unverschlüsselt.","Pfad muss zum Betrieb gehören, IBAN nur für berechtigte Rollen, Inhalte auf IBAN-Muster prüfen, Grenzen je Speicher, AU verschlüsselt.","C","1","live"),
("185","Schreibrechte der Mitarbeiter je Modul","An rund 175 Stellen dürfen Mitarbeiter über die Datenbank schreiben, auch wenn sie im Modul nur lesen dürfen. Lagerbewegungen dürfen sie löschen (GoBD). Abo-Rechnungen ohne Abrechnungsrecht.","Schreiben nur mit Modul-Schreibrecht, Löschen von Buchungen nur Chef, Abo-Rechnungen nur mit Abrechnungsrecht – schrittweise, SQL getrennt.","G","2","live"),
("186","Abläufe-Rest","Abläufe lassen sich nicht löschen. Ein abgestürzter Lauf bleibt ewig auf „läuft“. Ein nicht erreichbarer Webhook-Empfänger stoppt den Lauf ohne Neuversuch.","Löschen mit Rückfrage (Protokoll bleibt), hängende Läufe nach 2 Std. auf Fehler + Glocke, 3 Neuversuche über 24 Std.","C","1","live"),
("187","Sammelpaket klein","Prüf-Fälligkeiten rutschen einen Tag zurück und Monate laufen über (31.01. + 1 Monat = 03.03.). MRR-Kachel rechnet mit alten Preisen. Rechnungs-Knöpfe beim Mitarbeiter sichtbar. Artikel-Import überschreibt Filialbestände. Vereine bekommen Vertragsart „Studio“. Alte Crons nehmen das Geheimnis per URL. Keine volle CSP. 17 npm-Warnungen.","Jeden Punkt einzeln beheben, mit Tests; CSP zuerst im Beobachtungsmodus; Next.js 16.3.8 gegen Sicherheitslücken.","C","2","live"),
("187c","Speicher-Grenzen und Betrieb-Rest","Speicherordner ohne Größen- und Typgrenzen (HTML/SVG möglich). Korrespondenz, Bauplan-Pins, SEPA-Mandate und Nachkauf-Erinnerungen speichern beim Mitarbeiter unter eigener Kennung; Mitarbeiter legen Ratgeber-Seiten an, die nie erscheinen.","Grenzen je Speicherordner (großzügig über den Code-Grenzen), Speichern für den Betrieb, Ratgeber-Knopf nur für den Chef.","C","1","live"),
("187d","Personal-Cockpit schreibt für den Betrieb","Büroleitung mit Personal-Recht legt Mitarbeiter, Abwesenheiten, Schulungen, Dokumente usw. unter eigener Kennung an – der Chef sieht sie nicht, neue Mitarbeiter hängen am falschen Betrieb. Gleiches bei Tickets, Reports, Kalkulator-Normen.","Datenbank-Regeln mit Personal-Recht (wie Paket 181), dann Speichern für den Betrieb; Tabelle „mitarbeiter“ getrennt wegen Aussperr-Risiko.","G","2","live"),
("196","Elektro-Feinschliff","Prüfprotokolle haben keine Zahlenfelder für Messwerte, es fehlt die Erstprüfung nach VDE 0100-600; kein Elektro-Startkatalog, nur ein Kalkulator-Beispiel, keine Rechte-Vorlage „Monteur“.","Messwert-Felder mit Grenzwerten, Vorlage VDE 0100-600, Elektro-Startkatalog und Kalkulator-Beispiele (Zählerschrank, Wallbox, Unterverteilung), Rechte-Vorlage Monteur.","C","1","live"),
("197","Verschickte Rechnungen fest ablegen","Eine verschickte Rechnung wird nicht als PDF abgelegt; jedes Öffnen erzeugt sie neu aus den Daten. Jede spätere Änderung am Programm kann das Aussehen alter Rechnungen verändern.","Beim Versand wird das PDF unveränderbar abgelegt (mit Prüfsumme), Ansicht und Download zeigen danach immer genau dieses Dokument (GoBD).","G","1","live"),
("164·3","Zwei-Faktor auch in der Datenbank","Zwei-Faktor schützt nur die Seiten; mit gestohlenem Passwort sind Schnittstellen und Datenbank weiter voll nutzbar.","Datenbank-Regeln verlangen den bestätigten Code, danach Pflicht für alle einschalten. Hohes Aussperr-Risiko, mit Rückweg.","G","1","live"),
("198","Mahnungen und Zusagen fest ablegen","Mahnungen und Angebots-Zusagen werden bei jedem Öffnen neu erzeugt; verschickte Rechnungen bleiben bis „bezahlt“ änderbar; angenommene Angebote lassen sich nachträglich ändern.","Mahnungs-PDF und Zusage-Nachweis unveränderbar mit Prüfsumme ablegen, Rechnungen automatisch festschreiben (Zahlung, Mahnung, Zahlungsmeldung), angenommene Angebote gesperrt.","G","1","live"),
("199","Werbung: Bestätigung nachholen, Widerrufe, Bewertungen","Von Hand eingetragene Newsletter-Adressen bekommen nichts und lassen sich nicht bestätigen; die Seite kann „bestätigt“ selbst setzen. Nach der WhatsApp-Bestätigung kommt keine Antwort. Shop-Widerrufe sieht der Betrieb nur per Mail. Bewertungen zeigen den vollen Namen. „Unterlagen senden“ aus dem Kunden-Knopf ist ohne Werbe-Einwilligung blockiert.","Bestätigungs-Mail per Knopf nur mit Quelle + Datum der Einwilligung (höchstens 2, 7 Tage Abstand), Nachweis-Spalten nur noch vom Server, WhatsApp-„Danke, angemeldet“, Widerrufe auf der Retouren-Seite, Bewertungen als „Vorname + Initial“, Häkchen „Betriebspost“ am Kunden-Knopf.","C","1","live"),
("200","Rechte: Werkstatt-Bühne und „Angelegt von“","Die Werkstatt-Bühne verlangt das Recht „Buchungen“; wer einen Kontakt, ein Angebot, eine Rechnung oder einen Auftrag angelegt hat, sieht man nirgends.","Bühne auch mit Recht „Werkstatt“ buchbar, „Angelegt von“ in Kontakte, Angebote, Rechnungen, Aufträge.","C","1","live"),
("201","Mitglieder-Bankdaten schützen","Jeder Mitarbeiter kann über die Datenbank alle Mitglieder samt IBAN lesen (Regel mgd_select_ma).","Regel entfernen, Bankdaten in eigene Tabelle nur für Chef bzw. Mitglieder-Ändern-Recht. Getrennt geliefert (Aussperr-Hinweis).","G","1","live"),
("203","Zwei-Faktor-Ausnahmen je Mitarbeiter","Ohne Diensthandy muss der Chef die Zwei-Faktor-Pflicht für alle ausschalten.","Ausnahme-Liste je Mitarbeiter mit Grund und Nachweis. Getrennt geliefert (Aussperr-Hinweis).","G","1","live"),
("258","Speicher-Wächter nach AGB-Formel","Die Upload-Wege lasen die Tarif-Stufe aus einer Spalte, die fast nie passte: praktisch jeder Betrieb hatte 25 GB statt der AGB-Zusage 100 GB je Mitarbeiter.","Kontingent je Betrieb = Chef und Mitarbeiter × 100 GB, gepoolt, plus Zusatzblöcke, nie unter der alten Grenze; Mitarbeiter zählen zum Betrieb des Chefs; bei Störung 100 GB statt 25 GB. Getrennt geliefert.","C","1","live"),
("189","Voice Layer Stufe 2","Jede Wiedergabe erzeugt die Stimme neu und kostet jedes Mal.","Zwischenspeicher im privaten Speicher, gleiche Texte kosten nichts mehr.","C","1","wartet auf 188"),
("35–40","DSGVO-Werkzeuge (72er-Liste)","Verzeichnis und Auskunft haben 54 Lücken, es gibt keinen Löschweg für Leads, Webinar-Daten werden gelöscht statt gesperrt, keine Sperrung mit Fristen.","Vollständiges Verzeichnis mit Mustertexten, Löschweg, Sperren statt Löschen mit Fristen-Automatik – nach dem Anwalt.","C","2","wartet auf Anwalt"),
]))
S.append(("s3","Stufe 3 · Jetzt bauen","Neue Funktionen, ohne Pause bis kurz vor dem Anwalt – in dieser Reihenfolge",[
("B4","Shop aus Inventar","Die Übernahme ging nur über Filter; „Alle übernehmen“ stellte auch Artikel ohne Preis (0,00 €, so auch bestellbar) und ausgelistete Artikel in den Shop; jede Bestellung rechnete pauschal 19 % MwSt; Bilder nur per Adresse.","Übernahme per Häkchen-Auswahl oder Filter, nur aktive Artikel mit Preis (Rest mit Grund übersprungen), MwSt 19/7/0 % je Artikel, Foto-Upload, Filter „nur mit Bestand“; öffentlicher Shop zeigt und verkauft nur Verkaufsfähiges.","C","1","live"),
("S1","Kleines Sammelpaket aus dem Kontrollgang","Die Übungswelt nutzt echt existierende Beispiel-Domains; „Abmelden“ im Newsletter-Dashboard trägt nicht in die Sperrliste aller Kanäle ein.","Beispiel-Domains auf example.com, Abmelden wirkt in allen Kanälen.","C","1","live"),
("B5","Branchenverzeichnis-Eintrag","Einträge bei Google, Bing, Apple und den Verzeichnissen macht jeder Betrieb von Hand; Name, Adresse und Telefon stehen überall anders geschrieben.","Seite „Branchenverzeichnisse“: Eintrag aus den Firmendaten vorbereitet und überall gleich geschrieben (Telefon +49, Website https), jedes Feld per Klick kopieren, Beschreibung je Verzeichnis gekürzt, Lücken-Hinweis, abhaken mit Link und Datum.","C","1","live"),
("B3","Website-Texte aus Firmenwissen","„Komplett mit KI“ schrieb nur aus Name, Slogan, Über-uns und Story — Leistungskatalog und Firmen-Dokumente blieben ungenutzt; dazu erfand die KI immer Kundenstimmen („Beispiel-Bewertung“), die öffentlich erschienen.","KI nutzt Branche, Leistungskatalog (ohne Preise) und Firmen-Dokumente (vertraulich klingende nie), meldet die Quellen; statt erfundener Kundenstimmen der Baustein „Live-Bewertungen“ mit echten, freigegebenen Bewertungen; Schalter „Firmenwissen nutzen“.","C","1","live"),
("B1","Bausteine Presse, SEO-Texter, E-Book, Strategie, Social","Presse, SEO-Ratgeber, E-Book und Strategie gab es schon (Text-Werkstatt mit Prüf-Bestätigung). Bei Social fehlte sie: KI-Entwürfe aus dem Content-Fließband ließen sich ungeprüft posten oder einplanen; jeder Mitarbeiter konnte Beiträge anlegen und löschen.","KI-Entwürfe gekennzeichnet, Posten und Einplanen erst nach „Ich habe den Text geprüft“ (Textänderung hebt auf), auch im Zeitplan-Lauf; Beitrags-Schnittstelle mit Marketing-Recht. 1 statt 3 Pushes.","C","1","live"),
("B10","Fernhilfe: Bildschirm teilen","Braucht ein Mitarbeiter oder Kunde Hilfe, kann niemand sehen, was er gerade auf dem Bildschirm hat; es bleibt beim Beschreiben am Telefon.","Knopf „🆘 Hilfe“ oben im Dashboard: die Person wählt im Browser selbst Bildschirm, Fenster oder nur den ARGONAUT-Tab, schickt den Link an die Geschäftsleitung oder den ARGONAUT-Support, lässt den Helfer ausdrücklich zu; Bild direkt zwischen den Browsern, ohne Ton, ohne Aufzeichnung, rotes Band, jederzeit beenden, Passwort- und Bankfelder im ARGONAUT-Tab unscharf, Link 30 Min. gültig. 1 statt 2 Pushes.","C","1","live"),
("B7","Eigene Absender-Domain je Betrieb","Alle Kunden-Mails eines Betriebs (Rechnung, Termine, Newsletter, Abläufe …) gehen als „Firmenname <noreply@argonaut-os.com>“ – die Absender-Adresse gehört nicht dem Betrieb.","Betreiber legt die Domain im Command Center bei Resend an (Reiter „Absender-Domain“), der Chef sieht die DNS-Einträge in den Einstellungen; erst nach Bestätigung und Freischaltung gehen die Mails von z. B. rechnung@post.firma.de. Lehnt Resend die Domain später ab, geht die Mail automatisch über den Standard-Absender. Eine Domain nie bei zwei Betrieben. Scharf mit Env RESEND_EIGENE_DOMAINS=an (Pro 10 Domains, Scale 1.000).","G","1","live"),
("B9","Paket 2 Andocken","Die Menge im Kalkulator wird von Hand getippt, das Aufmaß mit Rechenweg kommt nie an. Die Projekt-Verknüpfung der Kalkulation gab es, gesetzt wurde sie nie – erfasste Stunden fließen nicht zurück, „Aus der Praxis lernen“ lernt nur aus den eigenen Schätzungen. Ob die geplante Marge gehalten hat, sieht niemand.","Kalkulator: „Menge aus Aufmaß übernehmen“ (Positionen ankreuzen, nur gleiche Einheit, Rechenweg bleibt), Projekt beim Speichern oder nachträglich verknüpfen; Liste zeigt Plan- gegen Ist-Stunden und die echte Marge (Ist-Lohn zum Kostensatz der Kalkulation, Projektkosten, gleicher Gemeinkosten-Zuschlag), Klartext-Hinweise; Zeit-Normwerte aus echten Projekt-Stunden als Vorschlag (Vorrang vor Schätzungen, nichts automatisch). 1 statt 2 Pushes.","G","1","live"),
("B6","Mitbewerber-Funktionen Top 15","Unklar, welche gängigen Funktionen führender Mitbewerber noch fehlen. Die Plantafel ging nur per Klick → Fenster → Datum und Monteur ändern → Speichern.","Abgleich mit 15 führenden Anbietern (intern, ohne Namen nach außen): 14 der 15 kaufentscheidenden Funktionen sind gebaut, Großhandels-Bestellung IDS/OCI hängt an Partner-Zugängen. Gebaut: Plantafel per Ziehen und Ablegen (Monteur, Tag, „Unzugeordnet“; Uhrzeit und Dauer bleiben; Rückfrage bei fehlender Befähigung oder Überschneidung; laufende und erledigte Einsätze bleiben fest). Weitere Lücken als B6b und B6c.","C","1","live"),
("B6b","Foto-Markierung im Bautagebuch","Fotos im Bautagebuch lassen sich nur hochladen und ansehen; ein Mangel ist auf dem Bild nicht eindeutig zu zeigen.","Knopf ✎ am Foto: Pfeil, Kreis, Rahmen, Freihand und Text mit Finger oder Maus, vier Farben, Rückgängig. Das Original bleibt unverändert (Beweisfoto), die markierte Fassung wird zusätzlich abgelegt (große Handyfotos auf 2.400 px verkleinert).","C","1","live"),
("B6c","Angebot aus Sprache oder Notiz","Im Mitbewerber-Abgleich als Lücke geführt — Prüfung am Code: gibt es schon seit Paket G01 (24.09.2026).","Im Angebotsformular „Angebot per Sprache/Foto“: diktieren, tippen oder Aufmaß-Zettel fotografieren, Positionsvorschlag mit Preisen nur aus Leistungskatalog oder belegter Preisliste. Kein neuer Push nötig.","C","0","live"),
("B11a","Dossier-Generator für alle 698 Branchen","Nur das Elektro-Dossier ist fertig; jede Branche braucht ein eigenes, korrektes Verkaufsdossier.","Generator nach dem Elektro-Richtwert: echte Module je Kategorie, Branchen-Beispiele, „in Vorbereitung“ mit Begründung, QR auf die Branchenseite – jetzt nur der Generator, noch keine Dossiers rausgeben.","C","1","live"),
("B11c","Fachdossier-Texte für alle freien Branchen","Der Generator lieferte für fast alle Branchen nur Entwürfe ohne geprüften Text; Sperren für heikle Bereiche (Gesundheit, Recht, Tiere, Kasse, Shop) und Start-Schalter fehlten; im Dossier stand „alles inklusive“ und der Agentur-Kostenvergleich.","Pakete 215–256: Kostenvergleich und „alles inklusive“ raus, Start-Schalter und Widerrufsbutton, Sperr-Gedächtnis mit Wächter-Test, dann Texte in Wellen je Bereich – nur gebaute Module, keine Rechts-, Norm- oder Zahlenversprechen, jede Welle mit eigenem Test und Gegenproben. Stand: 385 von 698 mit Text, 206 gesperrt bis zur Anwaltsprüfung, 107 bewusst zurückgestellt (Begründung je Test).","C","42","live"),
("B2","KI-Telefonassistent","Anrufe außerhalb der Zeiten gehen verloren; kein Telefon-Baustein.","Partner Retell oder Vapi, Termine und Anfragen landen im System, KI-Hinweis am Telefon.","G","2","wartet auf Partner"),
("B8","Echte Anmeldung Marketing-Plattformen","Zugänge zu Meta, Google, LinkedIn, TikTok werden von Hand eingetragen.","Anmeldung per Plattform-Login (OAuth), Zugänge verschlüsselt.","G","2","wartet auf App-Prüfung"),
("L1","Neues Logo: Segel-A","Überall stand noch das alte Dreizack-Zeichen aus der Anfangszeit (Emoji-Screenshot, nicht schützbar), dazu 🔱-Emojis auf Webseite, Kundenseiten, Dossiers und E-Books; Browser-Tab und App-Symbole waren Platzhalter.","Martins Segel-A (07.10.) vektorisiert: eine zentrale Form für Web, App und PDF-Zertifikat; Favicon, Apple- und App-Symbole, Linkvorschau, SVG in Gold/Schwarz/Weiß/Navy, Druck- und Social-Exporte. Alle 27 Emoji-Stellen ersetzt; Angebot und Kundenportal zeigen nur den Betriebsnamen. Offen: Markenrecherche DPMA/EUIPO (Anwalt).","C","2","live"),
("D1","Datensicherheit und Upgrade-Pfad","Hochgeladene Dateien liegen nur bei Supabase; die Wiederherstellung auf Zeitpunkt sichert nur die Datenbank, nicht die Dateien. Geht ein Kunden-Archiv verloren, haftet ARGONAUT. Kein festgelegter Plan, ab wann Rechenleistung, CDN-Stufe und Mail-Tarif hochgestuft werden.","Nach dem Bau, gemeinsam: zweite Kopie aller Dateien außerhalb Supabase (Auswahl Hetzner Object Storage Deutschland, Cloudflare R2, Backblaze B2 EU), versioniert und gegen Löschen gesperrt; Rücksicherung einmal echt üben. Alles streng je Betrieb getrennt: eigener Ordner, eigenes Kontingent, Export und Löschen je Betrieb. Upgrade-Stufen mit Auslösern festlegen (Supabase Large → XL → 2XL, Vercel CDN-Stufen, Resend Scale → Enterprise, Newsletter-Kontingent je Betrieb). Lieber ein paar Euro mehr für Sicherheit.","G","2","offen"),
]))
S.append(("kfz",'Stufe 3b · Kfz-Pilot','Nach den Fachdossiers · voller Umfang der führenden Kfz-Systeme plus eigene Extras, vom Gebrauchtwagenhändler bis zum Luxushaus · Branchen-Vorlage und Partner-Netzwerk als allgemeiner Kern, Kfz zuerst · 13 SQL-Blöcke · Abgleich mit Code 06.10. · 15 Rechtsfragen · Plan im Doc „ARGONAUT Bauplan Kfz-Handel“',[
('BV','Branchen-Vorlage (Kern)','Heute ist je Bereich festgelegt, welche Module ein Betrieb bekommt, und je Branche nur die Wortwahl. Spalten, Status, Ampeln, gespeicherte Suchen und Chef-Kacheln sind nicht je Branche vorbelegt.','Eigene Schicht Branchen-Vorlage: Vorbelegung je Bereich, Feinschliff je Branche, Kundenänderungen obendrauf (eigene Spalten, Felder, Status bleiben bei jedem Vorlagen-Update erhalten). Kfz ist die erste Vorlage, K1 nutzt sie von Anfang an.','C','1','live'),
('K1a','Fahrzeugbestand Teil 1','Es gibt Kundenfahrzeuge (Werkstatt, HU/AU, Reifenhotel), aber keinen Handelsbestand: keine Standtage, kein Status, keine Sparten, keine Vorführwagen- oder Kommissions-Kennzeichen.','Handelsbestand als Liste und Karten, Status Zulauf bis Archiv, Sparten PKW bis Wohnmobil, Standtage-Ampel, Massenbearbeitung, gespeicherte Suchen, Listendruck; Verknüpfung mit der Lebensakte per FIN.','C','1','live'),
('K1b','Fahrzeugbestand Teil 2','Bestandsliste nur am Bildschirm; die FIN ist gespeichert, aber noch nicht mit der Werkstatt-Lebensakte verknüpft; Eigene Felder fehlen im Bestand.','Bestandsliste als PDF mit den aktuellen Filtern, Hinweis „aus der Werkstatt bekannt“ über die FIN, Eigene Felder je Fahrzeug, Fotos-Platzhalter für K3.','C','1','live'),
('K2','Handelsakte','Die Fahrzeugakte kennt nur Werkstatt und Halter, nichts zum Verkauf; fehlende Fotos und CO₂-Angaben fallen nicht auf.','Reiter Überblick, Ausstattung, Bilder, Akte, Historie, Aktionen; Preisverlauf, Inserats-Ampel, Titel-Wächter, CO₂-Felder; Link zur bestehenden Lebensakte.','C','1','live'),
('K3','Fotos und Medien','Fahrzeugfotos nur einzeln, keine Reihenfolge, keine Aufnahme-Hilfe.','Handy-Upload mit Aufnahme-Schablone, Reihenfolge per Ziehen, Video; Schäden über die vorhandene Foto-Markierung.','C','1','live'),
('K4a','Ankauf und Bewertung Teil 1','Kein Ankaufsprotokoll, keine Bewertung von Ankaufsfahrzeugen.','Ankaufsakte mit Prüfprotokoll (24 Punkte), Schäden mit Foto und Markierung, Richtwerte je Schadensart, Höchstpreis nach § 25a oder Regelsteuer, Angebots-Ampel, Übernahme in den Bestand mit einem Klick.','G','1','live'),
('K4b','Ankauf und Bewertung Teil 2','Kein Ankaufschein, keine Online-Anfrage für Verkäufer.','Ankaufschein als PDF zum Unterschreiben (Schäden ohne Beträge, Unternehmen mit USt), Online-Ankaufformular mit eigenem Link für Webseite und Inserate, Ein-/Ausschalter, Mail an Betrieb und Eingangsbestätigung. Inzahlungnahme am Verkauf wandert zu K6.','G','1','live'),
('K5','Kalkulation und Provision','Provisionen nur aus Deals; Ertrag je Fahrzeug unbekannt.','Plan- und Nachkalkulation je Fahrzeug mit Standkosten und Gemeinkosten, Provision Verkäufer und Hereinnehmer, Kommission.','C','1','live'),
('K6','Verkaufsunterlagen','Kein Kaufvertrag, keine Reservierung, keine Zulassungsvollmacht.','Verkaufsvorgang je Fahrzeug (Doppelverkauf sperrt die Datenbank): Angebot, Reservierung, Quittung Anzahlung, Kaufvertrag (Verbraucher/Unternehmer, Verkürzung auf ein Jahr nur gesondert mit eigener Unterschrift), Zulassungsvollmacht, Empfangsbestätigung als PDF; Inzahlungnahme aus dem Ankauf verrechnet; Unterschrift über ARGONAUT-Sign; ab 10.000 € bar kein Vertrag ohne GwG-Haken; Bestand-Status und Erlös in der Kalkulation ziehen mit; Übersicht „Verkäufe“.','G','1','live'),
('267','Stornorechnung als eigener Beleg','„Stornieren“ setzte nur den Status. Eine verschickte Rechnung brauchte für die Aufhebung einen eigenen Beleg mit Nummer und Verweis – den gab es nur als freies Dokument ohne Nummernkreis und Ablage.','Stornorechnung mit eigener Nummer aus dem Rechnungs-Nummernkreis, alle Positionen mit umgekehrtem Vorzeichen, Verweis auf das Original, sofort festgeschrieben, erstes PDF automatisch abgelegt, kein Zahlbetrag und kein GiroCode, Erstattungshinweis bei bezahlten Rechnungen; in einem Schritt in der Datenbank, nur Geschäftsleitung, kein Reaktivieren danach. Nie verschickte Rechnungen weiter per Status. Getrennt geliefert (Kern-Geld).','G','1','live'),
('K7','Rechnung Fahrzeugverkauf','§ 25a steht nirgends im Code; Gebrauchtwagen würden mit Umsatzsteuer ausgewiesen. Freitext-Empfänger standen ohne Anschrift auf dem PDF.','Rechnung aus dem Verkauf per Knopf: § 25a ohne Steuerausweis mit Pflichthinweis „Gebrauchtgegenstände/Sonderregelung“, Zulassung und Überführung mit 19 %; Regelsteuer centgenau auf den Vertragspreis (nie mehr); EU-Unternehmer und Ausfuhr steuerfrei mit Pflichthinweis und Nachweis-Hinweisen; Inzahlungnahme und Anzahlung mindern nur den Zahlbetrag; Differenzsteuer intern gespeichert; E-Rechnung mit E/K/G-Kategorie; Empfänger-Anschrift und USt-IdNr. auf jedem Rechnungs-PDF; Doppelschutz. Getrennt geliefert (Kern-Geld).','G','1','live'),
('269','Umsatzsteuer-Voranmeldung: § 25a, EU, Ausfuhr','Die Voranmeldung rechnet nur mit Netto und Steuer je Rechnung: eine § 25a-Rechnung erscheint als steuerfreier Umsatz, die Differenzsteuer fehlt; EU-Lieferungen und Ausfuhren landen ohne Kennziffer im Topf „steuerfrei“.','Marge netto der § 25a-Rechnung in Kz 81, Differenzsteuer in der Zahllast, der Verkaufspreis selbst wird nicht gemeldet; EU-Lieferung in Kz 41 (Hinweis Zusammenfassende Meldung), Ausfuhr in Kz 43; fehlt die Differenz, sagt die Seite laut „zu wenig gemeldet“. Rechnungen ohne Sonderfall unverändert. Getrennt geliefert (Kern-Geld).','G','1','live'),
('K9','Probefahrt und Vorführwagen','Fuhrpark und Verleih kennen keine Probefahrt und keine roten Kennzeichen.','Reiter „Probefahrt“ in der Handelsakte für Probefahrt, Vorführwagen, Ersatzwagen und Überführung: Führerschein nur als Prüfvermerk mit Klasse und Gültigkeit (keine Nummer), eigenes, rotes oder Kurzzeitkennzeichen (nie doppelt belegt), Übergabe und Rückgabe mit km, Tank und Schäden, Vereinbarung und Rückgabeprotokoll als PDF und zur Unterschrift; Kilometerstand der Akte zieht nach; Nachfass zwei Tage nach Rückgabe als Erinnerung; Übersicht „Probefahrten“ mit Überfällig, Nachfass und Fahrtenliste je rotem Kennzeichen.','C','1','live'),
('K10','Leads und Suchaufträge','Anfragen hängen nicht am Fahrzeug; Kundenwünsche gehen verloren.','Seite „Anfragen und Suchaufträge“: Anfrage mit oder ohne Fahrzeug, Quelle, Verantwortlicher per Klick, nächster Kontakt mit Ampel (überfällig/heute), Stand bis Gewonnen/Verloren mit Grund, Auswertung der Verlustgründe und Quellen, Abschlussquote; Suchaufträge mit 90 Tagen Laufzeit und Treffern aus dem Bestand („neu seit letztem Blick“); Hinweis in der Fahrzeugakte. Eigene Tabellen statt „leads“ — keine Werbe-Serie startet.','C','1','live'),
('K11a','Eigene Fahrzeugbörse','Keine eigene Fahrzeugbörse; Interessenten sehen den Bestand nirgends, Anfragen kommen nur per Telefon oder Mail.','Öffentliche Börse je Betrieb (Link zum Teilen, vom Chef ein- und ausschaltbar): nur inserierte Fahrzeuge in Bestand, Aufbereitung oder Zulauf, Filter und Sortierung, Detailseite mit Fotos, Preis als Endpreis (bei § 25a ohne Steuerausweis), Fahrzeugdaten, Energie und CO₂, Ausstattung, Unfall-Angabe ehrlich; Anfrage-Formular landet als Anfrage am Fahrzeug (Quelle Webseite, heute fällig) mit Mail an den Betrieb; bei Google auffindbar mit Fahrzeug-Strukturdaten (abschaltbar); EK, Kalkulation, FIN, Kennzeichen, Notizen nie öffentlich (Positivliste, Wächter-Tests); Impressum und Datenschutz-Hinweis des Betriebs; Hinweisleiste, wo Preis, Energie oder Firmendaten fehlen.','C','1','live'),
('273','Börse auf der Domain des Händlers','Die Börse lief nur unter argonaut-os.com; auf der Domain des Händlers zeigte /fahrzeuge die Startseite, Google hätte die Fahrzeuge unter unserer Domain geführt.','autohaus-domain/fahrzeuge zeigt die Börse (Betrieb nur über die Domain aus dem Website-Bauer, auch Subdomain), Google-Adresse immer auf der Händler-Domain, Menüpunkt „Fahrzeuge“ auf der Kunden-Webseite, Domain nur für die Börse leitet auf /fahrzeuge; offen „Präsentiert mit ARGONAUT OS“ im Fuß jeder Börse und Kunden-Webseite (nur Marke). Keine versteckte Weiterleitung über argonaut-os.com.','C','1','live'),
('274','Partner-Andockstelle und Fahrzeughistorie','Partner wie carVertical ließen sich nirgends anbinden; ein Historienbericht hing nicht am Fahrzeug, Käufer sahen in der Börse keinen Nachweis.','Muster für alle Partner: in der Schnittstellen-Zentrale je Partner zwei Wege, eigenes Konto verbinden (Schlüssel verschlüsselt) oder „Noch kein Konto? Hier abschließen“ direkt beim Partner (ARGONAUT vermittelt nur, verkauft nichts weiter). Erster Partner carVertical: Bericht-Link mit Datum in der Akte, „Fahrzeughistorie geprüft“ in der Börse nur mit Freigabe je Fahrzeug. Abruf per Knopf folgt mit K19.','C','1','live'),
('275','K12a Preise und Standzeit','Preise wurden nach Gefühl gesenkt: keine Untergrenze je Fahrzeug, kein Überblick über Standzeiten, keine Zahl, wie oft ein Fahrzeug in der eigenen Börse angesehen wurde.','Preis-Cockpit über den ganzen Bestand nur aus eigenen Daten: Untergrenze (Einkauf + Kosten + Standkosten + Mindest-Rohertrag), Standzeit-Verteilung mit gebundenem Einkauf, Aufrufe der Börse ohne Cookies, Anfragen, Inserats-Ampel, Einschätzung in Klartext; Vorschlag nur nach der eigenen Preis-Treppe (keine KI), Übernahme per Knopf mit Preisverlauf.','C','1','live'),
('276','K12b Marktvergleich','Ob ein Preis zum Markt passt, sah der Händler nur durch Suchen auf den Börsen; nichts davon landete am Fahrzeug.','Vergleichsangebote je Fahrzeug selbst erfassen (Preis, km, Erstzulassung, Quelle, Link, keine Namen); Marktmitte, Spanne als Balken, Rang und Abweichung, km-Hinweis; zählt nur Einträge der letzten 30 Tage, die nach km und Erstzulassung passen, ab 3 eine Aussage. Auch im Preis-Cockpit. Keine fremden Marktdaten, keine KI; lizenzierter Partner kann später andocken.','C','1','live'),
('277','K13 Brief-Tresor und Aufbereitung','Unklar, wo Fahrzeugbriefe und Schlüssel liegen, wer sie gerade hat und welches Fahrzeug in der Aufbereitung steht; der Brief konnte vor der Zahlung herausgegeben werden.','Tresor je Fahrzeug (Brief, Schein, Schlüssel, CoC, Serviceheft) mit Ort, Ausgabe an wen und bis wann, Verlauf nur durch die Datenbank; Brief an den Käufer gesperrt, solange Geld offen ist. Zulassungsauftrag (Zulassung, Ummeldung, Abmeldung, Ausfuhr, Kurzzeit) mit Unterlagen-Haken und eVB. Aufbereitung als interner Auftrag im Werkstatt-Board ohne Kundenrechnung, Kosten per Knopf in die Kalkulation. Übersicht mit überfälligen Ausgaben und Briefen nicht im Haus.','C','1','live'),
('278','K18a Partner-Netzwerk: Verbindung, Auftrag, Einträge','Jeder Betrieb ist streng getrennt; ein Händler kann seinem Aufbereiter, Lackierer oder Gutachter keinen Auftrag am Fahrzeug geben, der dort in die Akte schreibt. Passt für 390 von 698 Branchen (300 ohne Anwalt).','Verbinden per Einladungs-Code (nur Geschäftsleitung, 14 Tage, einmalig, jederzeit trennbar), Auftrag am Fahrzeug an den Partner mit Freigaben (km, FIN, Fotos), Partner sieht nur dieses Fahrzeug ohne Preise, Kunde, Kennzeichen und Notizen und nur, solange der Auftrag läuft; Annehmen/Ablehnen/Fertig/Abnehmen/Nachbesserung, Einträge und Fotos beider Seiten nicht änderbar (privater Ordner ohne Regeln, nur der Server), Glocke. Zugriff ausschließlich über geprüfte Datenbank-Funktionen.','G','1','live'),
('279','K18b Partner-Netzwerk: Gast-Link und Partner-Rechnung','Partner ohne ARGONAUT können nicht mitarbeiten; die Rechnung des Partners kommt per Mail und muss von Hand in Belegeingang und Kalkulation.','Gast-Link je Auftrag (nur Prüfwert gespeichert, 7–60 Tage, sperrbar, Mengen-Deckel, nie bei Google): Gast sieht nur diesen Auftrag, nimmt an, schreibt Einträge mit Fotos, meldet fertig. Partner (Betrieb oder Gast) reicht Rechnung ein (PDF/Foto, Netto, USt 19/7/0 %); Auftraggeber übernimmt sie per Knopf in Belegeingang (Fremdleistung, mit Datei) und Fahrzeugkosten — in einem Schritt, nie doppelt — oder weist sie mit Grund zurück. Rechtsfrage AV-Vertrag zwischen Betrieben (R47).','G','1','live'),
('280','K14 Chef-Blick Fahrzeughandel','Keine Auswertung, womit der Fahrzeughandel Geld verdient.','Nur Chef: Kacheln Monat/Quartal/Jahr gegen Vorjahr (Verkäufe, Erlös, Rohertrag, Deckungsbeitrag, Standtage), Rohertrag je Monat als Balken, Ertrag je Marke und Preisklasse, Zulauf und gebundener Einkauf, Verkäufer-Rangliste (Standard aus, § 87 BetrVG), Summen-Wächter in ganzen Cent. Karte im Chef-Blick, Quelle „Fahrzeughandel“ im Report-Baukasten. Kein SQL, keine KI.','C','1','live'),
('281','K15a Kaufstatus im Kundenportal','Käufer sehen den Stand ihres Kaufs nicht. Ein Verkaufsvorgang war nie mit einem Kontakt verknüpft — Rechnung und Portal kannten den Käufer nicht.','Karte im Reiter „Verkauf“: Käufer mit Kontakt verknüpfen (Vorschlag nur bei eindeutig gleicher E-Mail, sonst neu anlegen oder suchen), Kaufstatus-Link erstellen. Im Portal ab „reserviert“: Schritte bis zur Übergabe, Zulassung, Kaufpreis mit Anzahlung, Inzahlungnahme und Restbetrag, Stand des Fahrzeugbriefs — nie Einkauf, FIN oder Notizen. Kein SQL.','G','1','live'),
('282','K15b Finanzierungs-Beispiel und Konfigurator','Kein Finanzierungs-Beispiel; Zusatzleistungen (Winterräder, Garantie, Zulassung) kann der Interessent nicht selbst zusammenstellen.','Börse → Einstellungen: bis 12 Zusatzleistungen zum Ankreuzen (Preise rechnet der Server aus der Liste, Auswahl steht in der Anfrage). Finanzierungsbeispiel mit allen Pflichtangaben (§ 17 PAngV), effektiver Jahreszins aus den Raten, Rate auf den Cent aufgerundet; im Inserat nur mit Darlehensgeber, Anschrift, Sollzins und Bestätigung „Konditionen von der Bank“. Rechner fürs Verkaufsgespräch. ARGONAUT vermittelt keine Kredite. Kein SQL.','G','1','live'),
('283','K16a Fahrzeugbestand-Import und Bewertung DAT/Schwacke','Der Import kennt 81 Alt-Programme, aber kein Kfz-System; Händler tippen ihren Bestand ab. DAT- und Schwacke-Werte stehen nirgends am Fahrzeug.','Ziel „Fahrzeugbestand“ im Import-Center: eigene Listen und die mobile.de-Upload-Datei (feste Felder nach Handbuch), Monat/Jahr, PS → kW, ungültige FIN in die Notiz statt Zeile weg. Gruppe „Autohaus & Kfz-Handel“ (mobile.de belegt; Loco-Soft, WERBAS, Keyloop, incadea, AutoScout24 ehrlich „beim Hersteller erfragen“). Karte „Bewertung“ in der Akte: FIN kopieren, im eigenen DAT-/Schwacke-Konto abfragen, Händlerwerte eintragen, Vergleich mit dem eigenen Preis; Schnittstellen-Zentrale „Fahrzeugbewertung“ mit beiden Wegen. SQL getrennt.','C','1','live'),
('284','K16b DATEV: § 25a, EU und Ausfuhr richtig buchen','Der DATEV-Export kannte keine Kfz-Sonderfälle: ein Verkauf nach § 25a mit Zulassung landete als 7-%-Umsatz auf 8300 (DATEV hätte rund 1.347 € Steuer erfunden), ohne Zusatz steuerfrei auf 8200 — die Differenzsteuer fehlte. EU-Lieferung und Ausfuhr ohne eigenes Konto.','Kfz-Rechnungen werden aufgeteilt: § 25a Marge auf 8191/4136 (19 %), Rest ohne USt auf 8193/4138, EU 8125/4125, Ausfuhr 8120/4120, Zusatzleistungen wie üblich; Summe centgenau. Konten unter Schnittstellen → DATEV einstellbar, Fahrzeugnummer im Buchungstext, Hinweise vor dem Export; fehlen Positionen, wird nicht geraten. Kein SQL.','G','1','live'),
('285','K17a Musterbetrieb mit Handelsbestand','Der Musterbetrieb XXL hatte Werkstatt und Kundenfahrzeuge, aber keinen Handelsbestand — die Kfz-Seiten waren am Testtag leer.','8 Handelsfahrzeuge in jedem Status (Zulauf bis verkauft, auch Vorjahr für den Chef-Blick, ein Langsteher, ein Motorrad), Kosten, 4 Marktvergleiche, Anfragen, Suchauftrag, Probefahrt, Brief-Tresor, DAT-Bewertung. Kein Kaufvertrag, keine Rechnung, Börse bleibt aus. Kein SQL.','C','1','live'),
('286','K17b Kfz-Fachdossier','Das Fachdossier für den Kfz-Handel beschrieb noch Pipeline und Termine — nichts vom Kfz-Pilot (Ankauf, Börse, Probefahrt, Verkauf, Tresor, Kalkulation).','Kfz-Handel-Dossier neu nach dem Elektro-Richtwert: Alltag, Ablauf (Börse → Probefahrt → Kaufvertrag → Rechnung/Brief → Übergabe), Schwerpunkt Kalkulation je Fahrzeug und eine neue Seite „Ihr Fahrzeughandel im Detail“ (16 gebaute Funktionen, Partner carVertical, DAT, Schwacke über das eigene Konto). Nur Gebautes (Regel aus Paket 217) — Wartendes steht bewusst nicht drin. Neues PDF wird beim nächsten Abruf erzeugt. Kein SQL.','C','1','live'),
('297','K17c Vorführ-Autohaus mit Kfz-Fachdaten','Der Vorführ-Betrieb „Autohaus Renz“ hatte nur die Übungswelt (drei Kontakte, ein Angebot) — das KFZ-Fachpaket war leer, beim Vorzeigen sah man nicht, wie ein laufendes Autohaus in ARGONAUT aussieht.','Command Center → Vorführ-Betriebe → „🚗 Nur Autohaus“: Team, Kunden, 21 Fahrzeuge vom Zulauf bis verkauft (Porsche 911, GLE mit AMG Line, RS 6, Bentley im Zulauf, Langsteher), Verkäufe dieses Jahr und Vorjahr mit Verkäufer und erzieltem Preis (Chef-Blick), Kosten, Marktvergleich, DAT/Schwacke, Anfragen in jedem Stand, Suchaufträge, Probefahrten mit rotem Kennzeichen, Brief-Tresor, Zulassung, Ankauf mit Prüfung und Schäden, Verkaufsvorgänge, Werkstatt mit Kundenfahrzeugen und interner Aufbereitung, Ersatz- und Mietwagen, Termine. Rechnungen entstehen in der Vorführung per Knopf. Zurücksetzen löscht jetzt Kinder vor Eltern. Kein SQL.','C','1','live'),
('298','K17d Premium-Autohaus nach einem Jahr Betrieb','Zum Vorzeigen fehlte das andere Ende: ein großer Betrieb, der ARGONAUT seit über einem Jahr täglich nutzt — mit vollem Team, vielen Fahrzeugen, Verkaufshistorie und eigener Media-Abteilung.','Command Center → Vorführ-Betriebe → „🏁 Nur Premium-Autohaus“ (premium@demo.argonaut-os.com): Valtier Automobile mit 50 Mitarbeitern in Abteilungen (2 Geschäftsführer, Vertrieb 15, Media mit 2 Videocuttern, Werkstatt 14 …), rund 120 Premium-Fahrzeuge (Porsche, AMG, BMW M, Audi RS, Bentley, Lamborghini, Ferrari …), rund 500 Verkäufe über 21 Monate (Chef-Blick mit Vorjahr je Monat und Verkäufer-Rangliste), Anfragen, Probefahrten, Verträge, Ankauf, Tresor, Zulassung, Werkstatt mit Kundenfahrzeugen aus dem eigenen Verkauf, Erlebnis-Mietwagen, Urlaubsplan, Kampagnen, Inhalte-Bibliothek, Redaktionskalender und Schnitt-Aufgaben. Schreibt in Blöcken zu 500 Zeilen. Fotos und Videos lädt man selbst hoch. Kein SQL.','C','1','live'),
('299','K17e Zeitreise-Vorführung im Command Center','Die Vorführ-Betriebe waren nur über die Adresse erreichbar; beim Kunden fehlte der rote Faden „leer → nach einigen Monaten → nach 18 Monaten“.','Command Center: großer Block „🎬 Vorführ-Betriebe & Zeitreise“ direkt unter den Kennzahlen plus Kachel. Seite /admin/demo-betriebe beginnt mit der Zeitreise je Branche: Kfz Stufe 1 Autohaus Kessler (leeres Konto, Startstrecke 0 %, kfzstart@demo.argonaut-os.com), Stufe 2 Autohaus Renz (erste Monate), Stufe 3 Valtier Automobile (nach 18 Monaten) — je Stufe Zugangsdaten zum Kopieren, Anmeldung öffnen, alle Stufen mit einem Knopf anlegen. Weitere Branchen kommen in lib/demoZeitreise dazu. Nebenbei: alle USt-IdNr. der Vorführ-Betriebe mit gültiger Prüfziffer. Kein SQL.','C','1','live'),
('300','K17f Zeitreise für jede Branche','Die Zeitreise (leer → erste Monate → nach 18 Monaten) gab es nur für Kfz; für die Präsentation in jeder Branche fehlten das leere Konto und der volle Betrieb.','Für alle 19 Kategorien je ein leeres Konto (Stufe 1) und ein großer Betrieb nach 18 Monaten (Stufe 3) — das Handwerk vorn mit zwei Reihen (Farbwerk Steinhauser, Kälber Gebäudetechnik): Team in Abteilungen mit Monteuren und Azubis, Einsatzplanung, Baustellen mit Bautagebuch, Mängel, Aufmaße, LV, Nachträge, Wartungsverträge, Fuhrpark. Jede Branche: Kunden, Angebote, Aufträge, Rechnungen mit Zahlungen über 18 Monate mit wachsender Kurve (eigene Nummern je Betrieb), Belege, Termine, Projekte, Urlaub, Zeiterfassung, Leads, Kampagnen plus die Branchen-Module. Seite: Zeitreise je Branche, „Alle Zeitreisen anlegen“ Reihe für Reihe. Kein SQL.','C','1','live'),
('301','Menü: Unterseiten nur mit gebuchtem Modul','Im Menü standen bei jedem Betrieb Unterseiten fremder Module (z. B. Trinkgeld-Verteilung und Trackday & Kartbahn beim Autohaus) — ein Klick führte zurück auf die Startseite. Mitarbeiter sahen dagegen Unterseiten ihrer eigenen Module nicht (z. B. Kfz-Bestand). Dazu tote Links (Umzug: Banking, E-Rechnung; Einrichtung: Shop-Produkte; SEO: Website-Bauer) und drei veraltete Kfz-Hinweise.','Unterseiten ohne eigenen Schlüssel erben das Modul der Elternseite — Menü, Buchung, Starter-Modus, Standort und Mitarbeiter-Rechte folgen jetzt demselben Modul wie der Pfad-Riegel (rund 50 Unterseiten in allen Branchen). Test prüft je Branche: was im Menü steht, lässt sich öffnen; dazu Wächter gegen Links ins Leere. Kein SQL.','C','1','live'),
("305","FM1 Fahrzeugmappe: Kunden-Seite","Wer sein Auto verkaufen oder in Zahlung geben wollte, musste zum Autohaus fahren oder füllte ein schlichtes Formular ohne Fotos aus; der Händler fuhr Besichtigungen für Fahrzeuge, die er nie gekauft hätte.","Fahrzeugmappe unter dem bisherigen Online-Ankauf-Link und auf der Händler-Domain (/fahrzeug-verkaufen, Menüpunkt „Fahrzeug verkaufen“ automatisch, Knopf und QR-Code für fremde Webseiten): Wunsch verkaufen oder in Zahlung geben, Fahrzeugschein, 8 Pflichtfotos, Schäden mit Beschreibung, Kaltstart-Video (direkt auf der Seite in 720p aufgenommen, höchstens 60 Sekunden), Rundgang, Videobotschaft, TÜV, Serviceheft, Rechnungen, Preisvorstellung. Kamera direkt, jede Datei ansehen, neu aufnehmen, löschen; Schärfe und Helligkeit prüft das Handy selbst (keine KI). Zwischenspeichern, QR-Code „Am Handy weitermachen“. Geht nur an diesen einen Betrieb: Ankauf „In Bewertung“ mit Karte „Fahrzeugmappe“, Glocke, E-Mail; Einwilligung mit Fassung. Privater Speicher ohne Nutzer-Regeln, Link-Schlüssel nur als Prüfwert. SQL getrennt.","C","1","live"),
("306","FM2 Fahrzeugmappe: Händler antwortet","Der Händler sah die Mappe, antwortete aber per Telefon oder Mail; der Verkäufer sah keinen Stand und konnte nichts nachreichen; die Fahrzeughistorie lag nirgends am Ankauf; angefangene und abgelehnte Mappen blieben für immer im Speicher.","Karte „Fahrzeugmappe“: Fahrzeughistorie (FIN kopieren, carVertical im eigenen Konto, Bericht-Link, Befund km/Unfall/Diebstahl mit Ampel), Antwort Angebot unter Vorbehalt (fester Vorbehaltstext, Betrag, gültig bis), Einladung zur Besichtigung, Rückfrage (14 Tage nachreichen), Absage; die Datenbank zieht Ankauf-Status und Angebot nach (angekaufte nie), Verlauf nicht änderbar. Verkäufer: E-Mail im Look des Autohauses mit Knopf zu seiner Mappe (Schlüssel verschlüsselt), Stand-Seite mit Angebot, Termin passt, Nachricht, Nachreichen (nur ergänzen). Löschfrist täglich: Entwürfe nach 30 Tagen, Absagen nach 90 Tagen, ohne Ankauf sofort — mit allen Dateien. SQL getrennt.","C","1","live"),
("307","FM3 Fahrzeugmappe: Auslesen und Übernahme","Daten aus dem Fahrzeugschein tippte der Verkäufer ab; Fotos der Mappe kamen nicht mit in den Bestand; ob der Verkäufer in Zahlung geben will, stand nur im Text.","Verkäufer: „Angaben automatisch ausfüllen“ liest Marke, Modell, FIN, Erstzulassung, Leistung und Kraftstoff vom Fahrzeugschein — nur Vorschläge zum Anhaken, nie automatisch übernommen, keine Namen/Anschrift, höchstens 3 Versuche je Mappe, KI-Kosten beim Betrieb; Feld Leistung (kW) neu, Notiz am Ankauf „automatisch erkannt“. Händler: „Ankaufen und in den Bestand übernehmen“ kopiert die Fahrzeugfotos gleich in die Fahrzeugakte (auf ihre Ansicht der Schablone), weitere Fotos, Schäden und Videos per Auswahl; Fahrzeugschein, Unterlagen und Videobotschaft nie. Hinweis bei Inzahlungnahme. Motiv-Prüfung der Pflichtfotos bewusst nicht gebaut (Kosten je Foto, Schärfe-Hinweis gibt es schon). Kein SQL.","C","1","live"),
("308","FM4 Fahrzeugmappe: Bewertungs-Empfehlung","Wer eine Mappe bewertete, recherchierte den Marktwert von Hand und rechnete Zustand, Pflege und Historie im Kopf ein; Marktvergleich und DAT/Schwacke gab es nur am Bestandsfahrzeug, nicht beim Ankauf.","Reiter „Bewertung“ im Ankauf: Marktvergleich und DAT/Schwacke-Werte jetzt auch am Ankauf (gehen beim Ankaufen mit an das Bestandsfahrzeug), Karte „Bewertungs-Empfehlung“: Marktspanne, empfohlener Verkaufspreis aus Marktmitte (ab 3 Vergleichen) bzw. DAT/Schwacke-Wert, Zu- und Abschläge, die das Autohaus selbst festlegt (Serviceheft, Vorbesitzer, Unfall, Historie, Zustand, Nichtraucher; Start 0 %, je ±30 %, zusammen ±40 %), höchster Einkaufspreis über die vorhandene Bewertungsrechnung, Begründung und Rechenweg, „Als geplanten Verkaufspreis übernehmen“. Keine KI, kein geschätzter Preis; zu wenig Daten wird ehrlich gesagt. mobile.de-Marktdaten erst mit lizenziertem Zugang (K11b). SQL getrennt.","C","1","live"),
('C1','Einwilligungs-Fenster und Besucher-Tracking mit Cookies','Kunden-Webseiten und Börse zählen nur ohne Cookies (Tageskennung); wiederkehrende Besucher und Kampagnen-Wege über mehrere Tage sind nicht messbar.','Eigenes Einwilligungs-Fenster (Annehmen und Ablehnen gleichwertig, Nachweis, jederzeit widerrufbar), erst danach eigenes Tracking-Cookie, Daten bleiben bei ARGONAUT (kein Google Analytics); wer ablehnt, wird weiter ohne Cookies gezählt; Datenschutz-Text des Betriebs ergänzt. Nach dem Kfz-Pilot, mit Anwalt-Punkt (§ 25 TDDDG).','G','2','offen'),
('310','BV2a Projekte nach Branchen-Vorlage','Projekte sahen in jeder Branche gleich aus: immer „Projekt“, immer „Aktiv/Pausiert/Abgeschlossen“, feste Warnschwelle 14 Tage/70 %; überfällige Aufgaben färbten die Ampel nie rot, weil die Fälligkeit gar nicht geladen wurde.','Projekte nutzen die Branchen-Vorlage: Handwerk und Bau „Baustelle“ (In Ausführung, Ruht, Fertiggestellt, Storniert, „Ohne Bauleiter“), Kanzleien „Mandat“, Veranstalter „Veranstaltung“, Agentur/IT „Kundenprojekt“, alle anderen „Projekt“. Schnellsuche (Kritisch, Achtung, Ende in 14 Tagen, Hoch und dringend, ohne Verantwortlichen), „⚙️ Ansicht“ für die Geschäftsleitung: Status-Namen, Angaben auf der Karte, Achtung-Schwelle. Ampel rechnet mit Kalendertagen und lädt die Fälligkeit der Aufgaben. Kein SQL.','C','1','live'),
('311','BV2 Aufträge nach Branchen-Vorlage','Aufträge sahen in jeder Branche gleich aus: immer „Lieferdatum“, immer „In Bearbeitung/Abgeschlossen“, kein Kunde und kein Termin in der Liste; fertige Aufträge ohne Rechnung fielen nicht auf.','Aufträge nutzen die Branchen-Vorlage: Handwerk und Bau „Ausführungstermin“ (In Ausführung, Fertiggestellt), Kanzleien „Frist“ und „Mandant“, Veranstalter „Buchung“ (Option, Gebucht, Durchgeführt), Agentur/IT „Abgabetermin“ (Abgenommen). Liste mit Kunde, Termin-Ampel (überschritten rot, bald gelb) und Spalte „Abgerechnet“; Schnellsuche (Termin überschritten, in 7 Tagen, fertig aber nicht abgerechnet, ohne Kunde, alte Entwürfe); Kachel „davon n nicht abgerechnet“; „⚙️ Ansicht“ für die Geschäftsleitung (Status-Namen, Spalten, Wort für den Termin, Achtung-Schwelle); Auftrags-Akte mit denselben Wörtern. Kein SQL.','C','1','live'),
('312','BV2 Kunden (CRM) nach Branchen-Vorlage','Kontakte zeigten den Status klein und roh („interessent“, „kunde“), jede Branche hatte 30 Tage Betreuungs-Takt — im Handwerk war damit fast jeder Kunde „einschlafend“; keine Schnellsuche, feste Spalten.','Status-Namen je Branche (Handwerk Anfrage, Im Gespräch, Kunde, Ruht; Kanzlei Anfrage, Erstgespräch, Mandant; Agentur/IT Lead), Wort für die Kunden („Mandanten“), Betreuungs-Takt für neue Kontakte (Handwerk 180, Kanzlei und Veranstalter 90, sonst 30 Tage), Ampel mit Kalendertagen; Schnellsuche (einschlafend, bald fällig, Wiedervorlage fällig, noch nie kontaktiert, ohne E-Mail); Spalten Wiedervorlage und Quelle zuschaltbar; „⚙️ Ansicht“ für die Geschäftsleitung; Kontakt-Akte mit denselben Wörtern. Kein SQL.','C','1','live'),
('313','BV2 Einsätze (Dispo) nach Branchen-Vorlage','Das Dispo-Board sprach überall von „Monteuren“, auch bei Reinigung, Veranstaltern oder IT; vergessene oder nicht abgerechnete Einsätze fand man nur durch Durchblättern der Wochen.','Wort für die Person je Branche (Monteur, Reinigungskraft, Crew, Techniker, sonst Mitarbeiter) und Status-Wörter (Auf der Baustelle, Im Objekt, Beim Kunden), auch in „Meine Einsätze“; Schnellsuche über alle Wochen mit Anzahl (vorbei und nicht erledigt, heute, erledigt aber nicht abgerechnet), Kalendertag in Berliner Zeit; „⚙️ Ansicht“ für die Geschäftsleitung. Damit ist BV2 abgeschlossen. Kein SQL.','C','1','live'),
('332','BV2b Teil 1 Vorlagen-Technik für Einzelstücke','Der Fahrzeugbestand kannte nur Autos: FIN, km, Erstzulassung — keine Seriennummer, keine Betriebsstunden, keine Merkmale für Boote, Maschinen, Uhren oder Kunst.','Sieben Arten (Fahrzeug, Boot, Maschine, Uhr/Schmuck, Kunst/Antiquität, Fahrrad, Gebrauchtware) mit Begriffen (Wort, Kennung, Zähler, Hersteller-/Modell-/Datums-Wort), Merkmal-Satz je Art (nur bekannte Felder, geprüft, öffentlich nur per Positivliste — Provenienz und Liegeplatz nie), Kfz-Teile je Art (FIN, Zulassung, CO₂ nur Straßenfahrzeug), GwG-Schwelle je Art (allgemein bar ab 10.000 €, Edelmetall bar ab 2.000 €, Kunst ab 10.000 € jede Zahlart — Anwalt). Branchen-Vorlagen für Maschinen, Uhren/Schmuck, Kunst/Antik, Fahrrad, Second Hand; „Bootcamp“ ist kein Bootshandel mehr. Suchregeln bh und art. SQL p332: art, merkmale, betriebsstunden, seriennr am Bestand (keine Regel geändert).','C','1','live'),
('333','BV2b Teil 2 Bestandsliste nach Art','Die Bestandsliste sprach nur Auto: FIN, Kennzeichen, Erstzulassung, km und PS — auch beim Boot, der Maschine oder der Uhr.','Liste und Formular in den Wörtern der Art: Art je Stück wählbar (Vorgabe aus der Branche), Hersteller-/Modell-Wort, Seriennummer bzw. Rumpfnummer statt FIN, Betriebsstunden statt km, Baujahr auch nur als Jahr, Kennzeichen nur mit Zulassung, Merkmale je Art im Formular (intern markiert, was nie ins Inserat geht) und als Spalte (abwählbar), PDF-Liste mit passenden Spaltenköpfen, Suche auch über die Seriennummer. Für die Art ausgeblendete Felder bleiben unverändert gespeichert. Ohne SQL p332 läuft alles wie bisher als Kfz. Kein SQL.','C','1','live'),
('334','BV2b Teil 3 Akte nach Art','Die Akte eines Boots, einer Uhr oder eines Gemäldes zeigte Energie und CO₂, Probefahrt, Brief-Tresor, HU, Polster, DAT/Schwacke und Auto-Ausstattung – und die Inserats-Ampel zog 25 % ab, weil CO₂-Angaben fehlten.','Akte in den Wörtern der Art: Kopfzeile mit Baujahr und Betriebsstunden, Kennung statt FIN, Merkmale-Karte (intern markiert 🔒), Reiter nur, wo die Art sie hat (Energie/CO₂ nur Kfz, Probefahrt für Fahrzeug, Boot, Maschine, Fahrrad, Brief und Schlüssel für Fahrzeug und Maschine), HU, Polster, Werkstatt-Lebensakte, Fahrzeughistorie und DAT/Schwacke nur bei Fahrzeugen. Inserats-Ampel zählt bei Einzelstücken die Merkmale statt CO₂. Ausgeblendetes bleibt unverändert gespeichert; ohne SQL p332 wie bisher. Kein SQL.','C','1','live'),
('335','BV2b Teil 4 Börse und Inserat nach Art','Die öffentliche Börse zeigte bei Booten, Uhren oder Kunst Erstzulassung, Kilometer, kW, Kraftstoff und CO₂ und meldete sie Google als „Auto“; Merkmale wie Länge oder Rumpf fehlten.','Börse liest zusätzlich Art, Merkmale und Betriebsstunden (Seriennummer nie). Einzelstücke zeigen nur ihre Angaben: Baujahr bzw. Entstehung, Betriebsstunden oder km je Art, die öffentlichen Merkmale (Liegeplatz, Provenienz, Edelmetall-Haken bleiben intern), HU nur mit Zulassung, Fahrzeughistorie nur mit FIN, keine CO₂-/Kraftstoff-/Leistungsangaben; „Schäden“ statt „Unfall“ bei Uhren, Kunst und Gebrauchtware; für Google als Product statt Car. Autos unverändert; ohne SQL p332 wie bisher. Kein SQL.','C','1','live'),
('336','BV2b Teil 5 GwG-Schwelle je Art im Verkauf','Der Verkauf kannte nur eine Geldwäsche-Grenze: 10.000 € bar. Edelmetall (Grenze 2.000 € bar) und Kunst (10.000 € unabhängig von der Zahlart) wurden nicht erkannt; Uhren und Kunst verlangten bei der Übergabe einen Kilometerstand.','Grenze je Art aus der Einzelstück-Vorlage: Edelmetall-Haken bar ab 2.000 €, Kunst ab 10.000 € jede Zahlart, sonst bar ab 10.000 €. Kasten, Fehler und Hinweise nennen „Bargeld“ bzw. „Kaufpreis“ und die richtige Grenze, ohne Haken kein Kaufvertrag; die Verkaufsübersicht zählt „GwG offen“ je Art. Kilometer bei der Übergabe nur bei km-Zähler, FIN-Hinweis nur bei Fahrzeugen, Brief-Hinweis nur mit Papieren. Grenzen vor dem Einschalten vom Anwalt bestätigen lassen. Kein SQL.','C','1','live'),
('337','BV2b Teil 6 Freischaltung für Händler von Einzelstücken','Juweliere, Kunst- und Antiquitätenhandel, Second Hand, Land- und Baumaschinenhandel, Galerien und Werften bekamen das Bestands-Modul nicht; wer es hatte, sah im Menü „KFZ-Fachpaket“ und HU/AU-Listen.','Beim Einladen einer solchen Branche schaltet das Command Center das Modul zusätzlich frei (nur neue Betriebe, bestehende bleiben unverändert; Hersteller und Verleih bekommen es nicht). Menü und Startseite in den Wörtern der Art („⌚ Uhren und Schmuck“, „⛵ Bootsbestand“), Probefahrt und Brief-Tresor nur, wo die Art sie hat, Schadenabwicklung nur bei Fahrzeugen; Kunden-Fahrzeuge (HU/AU) und Reifenhotel auf Knopfdruck. Kein SQL.','C','1','live'),
('338','BV2b Feinschliff Börse, Preis-Cockpit und Hilfe nach Art','Die öffentliche Börse eines Boots- oder Uhrenhändlers hieß „Unsere Fahrzeuge“ mit Kraftstoff-Filter und Kilometer-Sortierung; das Preis-Cockpit zog Einzelstücken 25 % Inserats-Punkte für fehlende CO₂-Angaben ab; die Hilfe kannte nur Autos.','Börse in den Wörtern der Art des Betriebs („Unsere Boote“, „Alle Maschinen“, „Anfrage zu dieser Maschine“, Hersteller-Wort im Filter), Kraftstoff-Filter nur mit Werten, Kilometer-Sortierung nur bei km-Zähler; Autos wortgleich wie bisher, Art aus der Branche, jeder Lesefehler = Kfz. Preis-Cockpit zählt bei Einzelstücken die Merkmale wie die Akte (ohne SQL p332 wie bisher). Hilfe-Einträge für Fachpaket, Bestand und Preis-Cockpit ergänzt. BV2b damit komplett. Kein SQL.','C','1','live'),
('BV2b','Handel mit Einzelstücken (Rest)','Immobilienmakler haben noch keine Objektbörse.','Immobilien-Objektbörse erst nach dem Anwalt (+2 Pushes, dann neu einplanen).','C','0','wartet auf Anwalt'),
('331','PS-1 Preis-Spiegel für Dienstleister','Friseur, Gastronomie oder Handwerk wussten nicht, wo ihre Preise im Umfeld liegen.','Leistungskatalog → „📊 Preis-Spiegel“: Posten aus dem Katalog (eigener Preis brutto daraus: Pauschale, sonst Standardmenge × Stundensatz, Menge je Einheit) oder freier Posten wie ein Gericht; Mitbewerber-Preise von Hand (Kennung wie „Mitbewerber A“, keine Personennamen, Telefon/E-Mail/Link abgelehnt), brutto oder netto, Quelle, Entfernung, Datum, Link. Je Mitbewerber zählt der neueste Eintrag der letzten 180 Tage; ab 3 Marktmitte, Spanne, Balken, Preisklasse (Quartile), Abstand in %, Übersicht und Filter. Kein Auslesen, keine KI-Schätzung. SQL p331 (2 Tabellen, Wächter p331).','C','1','live'),
('339','BV3a Teil 1 Reife-Uhr für Manufakturen','Reifestücke (Dry-Aged, Schinken, Salami, Käse, Wein, Confiserie) laufen über Zettel am Reiferaum: wann ist die Mindestreife erreicht, wann wird es zu lang, wie viel ist eingetrocknet, war das Klima im Soll?','Seite „⏳ Reife-Uhr“ unter Lebensmittel: Reife-Charge je Stück mit Art (Startwerte für Mindest-, Ziel- und Höchstreife, Temperatur und Luftfeuchte — änderbar), Nummer RF-JJJJ-001, Ampel jung/reift/bereit/überreif mit Daten, Reifeverlust aus den eigenen Wiegungen, Klima-Messungen mit Abweichung vom Soll, Hinweis nach 7 Tagen ohne Messung, Abschließen mit Endmenge oder Verwerfen. Messungen sind ein Nachweis: nie geändert, Fehleingaben löscht nur die Geschäftsleitung. SQL p339: reife_charge, reife_messung. Interne Dokumentation — keine Rezeptur, keine Sicherheitsaussage.','C','1','live'),
('340','BV3a Teil 2 Kalkulation mit Reifeverlust','Was kostet ein Kilo Dry-Aged wirklich, wenn ein Viertel eintrocknet und die Kruste weg muss? Bisher Kopfrechnung, und der Preis passt nach einer langen Reifung nicht mehr.','In der aufgeklappten Reife-Charge: Einkauf netto (je Einheit oder gesamt), Reifekosten je Tag, sonstige Kosten, erwarteter Reifeverlust, Parierverlust, Wunsch-Marge, Umsatzsteuer 0/7/19. Plan gegen Ist (letzte Wiegung vorläufig, Endmenge beim Abschluss endgültig): verkaufsfähige Menge, Ausbeute, Einstandspreis je kg, Preis-Vorschlag aus der Marge (reine Rechnung, keine Marktpreise), Marge und Rohertrag mit dem eigenen Preis, Verlustgrenze. Gramm wird je kg gerechnet. Eigene Tabelle reife_kalk (SQL p340): Preise sehen nur Geschäftsleitung und „Darf abrechnen“.','C','1','live'),
('341','BV3a Teil 3 Preis-Treppe nach Reife und MHD','Ein Stück, das länger reift, ist mehr wert; eines kurz vor dem MHD muss raus. Bisher wird der Preis an der Theke im Kopf angepasst, ohne Regel und ohne Schild.','MHD je Reife-Charge (alle mit Schreibrecht, Warnung ab 3 Tagen, überschritten rot). In der Kalkulation: Reife-Stufen (ab Tag X Aufschlag) und MHD-Stufen (X Tage vorher Abschlag) mit Startwerten je Art, „Preis heute“ und nächste Änderung; nach dem MHD kein automatischer Preis. Preisschild für die Theke (je kg/l, Reifetage, MHD, Charge) — bis zur rechtlichen Freigabe nur ENTWURF ohne Streichpreis (Start-Schalter reifePreisTreppe, R51 Preisangabenverordnung). SQL p341: reife_charge.mhd, reife_kalk.preis_treppe/mhd_treppe.','C','1','live'),
('BV3a','Manufaktur','Premium-Lebensmittel (Dry-Aged, Käse, Wein, Confiserie) haben Chargen, Reifezeit und knappe Mengen — dafür gibt es kein Gerüst.','Fertig gebaut: Reife-Uhr, Kalkulation mit Reifeverlust, Preis-Treppe. Pilot Fleischveredler, dann Wein, Confiserie. Freischalten erst nach dem Anwalt (Lebensmittel, R51).','C','0','wartet auf Anwalt'),
('342','BV3b Teil 1 Vorbestellung und Vormerkliste','Knappe Ware (Dry-Aged, Weihnachtsgans, Saison-Pralinen) wird auf Zettel vorbestellt: mal zu viel zugesagt, mal vergessen, wer als Nächstes dran war — und wer angerufen werden wollte, steht nirgends.','Seite „🧺 Vorbestellung & Vormerkliste“ unter Lebensmittel: Vorbestell-Aktion mit Gesamtmenge, Abholzeitraum, Bestellschluss, Höchstmenge je Kunde, optional aus der Reife-Uhr. Vorbestellungen von Theke, Telefon, E-Mail; die Datenbank lässt nie mehr zu, als da ist (auch bei gleichzeitigem Buchen). Ausgebucht → Vormerkliste nur mit Einwilligung (Wortlaut und Zeitpunkt gespeichert, nicht änderbar); wird etwas frei, rückt die Liste der Reihe nach nach, 48 Stunden Zurückhalten, Telefon- und Mail-Link mit fertigem Text (ARGONAUT versendet nichts selbst). Abholliste je Tag, „nicht abgeholt“, Löschen erledigter Vormerkungen nach 30 Tagen. SQL p342: vorbestell_aktion, vorbestell_posten, vormerkung. Rein intern — Shop folgt in Teil 2.','C','1','live'),
('343','BV3b Teil 2 Vorbestellung im Shop-Schaufenster','Vorbestellen ging nur an der Theke, am Telefon oder per E-Mail — wer online schaut, sieht knappe Ware nicht und kann sich nicht vormerken lassen.','Vorbestell-Aktion mit Artikel verknüpfen (Preis vom Artikel, Pflichtangaben vom Etikett) und „im Shop zeigen“. Im Shop: eigene Kacheln über den Produkten mit Restmenge, Abholzeitraum, Bestellschluss, Höchstmenge, Preis je Einheit und LMIV-Pflichtangaben (Zutaten mit fetten Allergenen, Nährwerte, Lebensmittelunternehmer; Art. 14 LMIV, außer MHD). Knopf „Zahlungspflichtig vorbestellen“, Bezahlung bei Abholung, Endpreis nach Gewicht; ausgebucht → Vormerkliste nur mit eigenem Einwilligungs-Haken. Server prüft alles neu (Höchstmenge je Kunde über alle seine Bestellungen), Datenbank hält die Menge. Bestätigungs-Mail Deutsch/Englisch, Mail an den Betrieb. Karte zeigt, was für den Shop fehlt. Start-Schalter vorbestellShop aus (R53). SQL p343: im_shop.','C','1','live'),
('344','BV3b Teil 3 Box-Konfigurator mit Saison-Kapazität','Geschenkkisten, Präsentkörbe und Grillpakete werden auf Zettel zusammengestellt: Preis je Wunsch von Hand gerechnet, vor Weihnachten mehr zugesagt als gepackt werden kann, und am Packtag weiß niemand, wie viel Käse gebraucht wird.','Seite „🎁 Box-Konfigurator“ unter Lebensmittel: Box mit Grundpreis, Steuersatz und Bestellschluss; Fächer („2 Käse nach Wahl“) mit wählbaren Artikeln und Aufpreis; Kapazität je Tag (Zeitraum mit Wochentagen auf einmal anlegen). Bestellung an Theke, Telefon, E-Mail: Kunde wählt je Fach, die Datenbank rechnet den Preis selbst und lässt je Tag nie mehr Boxen zu als die Kapazität (Tag wird beim Buchen gesperrt). Allergene der Box = Vereinigung aus den Etiketten, Hinweis bei gemischten Steuersätzen, Packliste je Tag mit Summe je Artikel. SQL p344: box_vorlage, box_fach, box_option, box_kapazitaet, box_bestellung. Rein intern.','C','1','live'),
('BV3b','Feinkost (Rest)','Boxen sind noch nicht im Online-Shop bestellbar.','Fertig gebaut: Vorbestellung und Vormerkliste, Schaufenster im Shop (hinter Start-Schalter), Box-Konfigurator (intern). Box im Shop und Freischalten erst nach dem Anwalt (Lebensmittel, R52–R54; +1 Push, dann neu einplanen).','C','0','wartet auf Anwalt'),
]))
S.append(("alle","Stufe 3c · Für alle Branchen","Was jeder Betrieb braucht – aus dem Kfz-Pilot heraus für alle 698 Branchen",[
("287","RF1a Rechts-Freigaben-Zentrale","Heikle Funktionen (Ortung, Auswertungen je Mitarbeiter, Führerschein-Prüfung, Bonitätsprüfung, Kameras, Aufzeichnung) wären entweder für alle an oder gar nicht da; ob der Betrieb Mitarbeiter und Kunden informiert, einen Betriebsrat beteiligt oder einen Vertrag mit dem Dienstleister hat, weiß ARGONAUT nicht.","Seite „Rechtliche Freigaben“ (nur Chef): je Funktion Voraussetzungen als Häkchen, Betriebsrat, Zweck, Anbieter; Nachweis wer/wann/welche Fassung, 12 Monate gültig, Hinweis ab 30 Tagen vor Ablauf, neue Fassung = neu bestätigen, Widerruf mit Rückfrage, Protokoll unveränderbar. Datenbank-Prüfung rechts_freigabe_aktiv() für alle Funktionen. Vorlagen „folgen nach rechtlicher Prüfung“. SQL getrennt.","G","1","live"),
("288","RF1b Freigaben an die Funktionen anbinden","Die Verkäufer-Rangliste im Chef-Blick fragte nur einmal nach (§ 87 BetrVG) und hielt nichts fest; gesperrte Funktionen erklärten nicht, warum.","Rangliste nur noch mit gültiger Freigabe „Auswertungen je Mitarbeiter“ einschaltbar und sichtbar — läuft sie ab oder wird sie widerrufen, ist sie ausgeblendet. Gemeinsamer Baustein „Freigabe-Hinweis“ für alle künftigen Funktionen (gesperrt beim Laden und bei Fehlern). Täglicher Zeitplan: Glocke an die Geschäftsleitung ab 30 Tagen vor Ablauf, höchstens einmal je Woche. Kein SQL.","G","1","live"),
("289","F1a Führerscheinkontrolle für alle Betriebe","Wer Mitarbeitern Firmenwagen überlässt, muss die Führerscheine regelmäßig prüfen (sonst Halterhaftung) — es gab keinen Ort für den Prüfvermerk und keine Erinnerung.","Seite Fuhrpark → Führerscheinkontrolle: Prüfvermerk (Datum, Klassen, Ablauf der Karte, Ergebnis) ohne Nummer und ohne Kopie, nächste Kontrolle nach Intervall (Standard 6 Monate, früher bei Kartenablauf, bei Mangel sofort), Ampel und Verlauf je Fahrer, Fahrerliste. Gesperrt bis zur Rechts-Freigabe „Führerscheinkontrolle“ — die Datenbank prüft mit. Vermerke nicht änderbar. SQL getrennt.","C","1","live"),
("290","F1b Fahrtenbuch und Ladestrom","Für die Steuer braucht es ein zeitnahes, nachträglich nicht unbemerkt änderbares Fahrtenbuch; Ladestrom zu Hause wurde nirgends erfasst.","Fahrtenbuch je Fahrzeug (Datum, km Beginn/Ende, Art, bei Dienstfahrten Ziel und Zweck Pflicht, Privatfahrten ohne Ziel), Lücken/Überschneidungen sichtbar, „nachgetragen“ ab 7 Tagen, Ändern nur mit Grund — die Datenbank protokolliert alt/neu, Löschen nur Chef, Monatsabschluss sperrt endgültig. Ladestrom: kWh aus Zählerständen × Preis je kWh laut Vertrag, auf den Cent, Status erstattet (Chef). Keine Pauschalen im Code. SQL getrennt.","C","1","live"),
("302","J1 Jobticket, Dienstrad und Mobilitätszuschuss","Betriebe zahlen Zuschüsse zum Deutschlandticket oder ein Dienstrad, führen Nachweise aber in Excel; was steuerfrei ist und was in die Lohnabrechnung gehört, sieht niemand.","Personal → Jobticket & Mobilität: je Mitarbeiter Jobticket, Dienstrad (Rate des Betriebs und Eigenanteil per Gehaltsumwandlung), Ladestrom-Vereinbarung, Fahrtkosten-Zuschuss und Sonstiges mit Betrag in Cent, monatlich oder einmalig, Laufzeit und Nachweis (mit „gültig bis“). Hinweis für die Lohnabrechnung steht auf „mit Steuerberater klären“ — steuerfrei, pauschal oder steuerpflichtig nur mit Datum der Bestätigung durch den Steuerberater (auch als Datenbank-Regel); keine Steuersätze oder Pauschalen im Code. Fristen-Ampel (30 Tage) mit „Erinnerung anlegen“, Kosten je Monat der letzten 12 Monate (Ladestrom nach kWh aus dem Fahrtenbuch getrennt), Liste für die Lohnabrechnung je Monat als CSV fürs Steuerbüro. Rechte Personal, löschen nur Chef. SQL getrennt.","C","1","live"),
("303","N1a Betriebs-Netzwerk für alle Branchen","Das Partner-Netzwerk (K18) gab es nur im Kfz-Handel; Gewerke am Bau, Subunternehmer, Freelancer, Zulieferer und Reinigungs- oder Hausmeisterdienste arbeiteten weiter per Mail und Telefon.","Betriebs-Netzwerk (Menü Betrieb): Verbindungen, Aufträge von Partnern und eigene Aufträge an Partner an Projekt, Auftrag oder Objekt (Kfz weiter am Fahrzeug) — gleiche Seite für Kfz und alle Branchen. Partner sieht nur Name des Bezugs und seine Aufgabe, nie Kunde, Adresse, Preise; nur solange der Auftrag läuft. Gast-Link für Partner ohne ARGONAUT, Einträge mit Fotos, Partner-Rechnung per Knopf in den Belegeingang (bei Fahrzeugen zusätzlich Fahrzeugkosten). Rechte je Art in der Datenbank: Projekte, Aufträge, Objektzeiten bzw. Kfz; Glocke führt auf die richtige Seite. SQL getrennt.","C","1","live"),
("304","N1b Netzwerk-Knöpfe in Projekt, Auftrag, Objekt","Partner-Aufträge vergab man nur über das Betriebs-Netzwerk; in Projekt-, Auftrags- und Objekt-Seite sah man nicht, was an Partner vergeben ist — und Mitarbeiter kamen gar nicht ins Netzwerk (der Pfad-Riegel schickte sie auch aus der Glocke auf „Mein Bereich“).","Knopf „🤝 An Partner geben“ mit Zähler laufender Partner-Aufträge (offen, angenommen, fertig) in Projekt-Akte, Auftrags-Akte und Objektzeiten je Objekt — führt direkt zum Bezug. Mitarbeiter mit Projekte, Aufträge, Objektzeiten oder Kfz sehen und öffnen das Betriebs-Netzwerk (kein eigener Modul-Schlüssel, Rechte je Auftrag weiter in der Datenbank). Kein SQL.","C","1","live"),
("309","SP1 „Was ARGONAUT Ihnen gespart hat“","Der Nutzen von ARGONAUT ist für den Chef nicht in Euro sichtbar — und für Social Media gibt es keine belegten Zahlen.","Karte im Chef-Blick nur mit belegten Werten aus den eigenen Daten: genutztes Skonto (neu: beim bezahlten Beleg unter Zahlungen eintragbar), abgelöste Programme laut Umzug mit den vom Chef eingetragenen Altkosten (nur volle Monate), ausgezahlte THG-Prämien, übernommene Datensätze statt Abtippen (Anzahl, keine Stunden) und geltend gemachte Verzugszinsen/Pauschalen (je Rechnung der höchste Stand, nicht in der Summe). Nichts geschätzt. Teilen als Text oder Bild nur nach Einwilligung des Betriebs, nur Summen ohne Namen. Angaben-Tabelle nur für die Geschäftsleitung. SQL getrennt.","C","1","live"),
]))
S.append(("mob","Stufe 3d · Mobilität","Nach dem Kfz-Pilot · Kfz-Gerüst für Vermietung, Zweirad, Flotte und Motorsport wiederverwenden · heikle Funktionen nur mit Rechts-Freigabe",[
("291–292","V1 Fahrzeugvermietung Kern","Autovermietung, Luxusverleih, Wohnmobil-, Transporter-, Motorrad- und E-Bike-Verleih hatten eine Branchenseite, aber kein Fachmodul.","Verleih → Fahrzeugvermietung: Mietflotte mit Preisen und Bedingungen (netto, Frei-km, Mehr-km, Kaution, Mindestalter, Führerschein seit, Klasse, Zusatzfahrer, Nachtanken je Achtel), Kalender 14 Tage, Buchung mit Vertragsnummer — Doppelbuchung sperrt die Datenbank, Preise eingefroren. Mietvertrag: Fahrer-Prüfvermerk ohne Nummer (die Datenbank rechnet Alter/Dauer/Klasse/Gültigkeit nach), Kaution nur Art/Status/Vorgangsnummer (Kartennummern gesperrt), Übergabe/Rückgabe mit km, Tank, Fotos (danach unveränderlich), Schäden mit Fotos, eigene Mietbedingungen je Fassung, Druckansicht, Rechnung (Miete, Zusatzfahrer, Mehr-km, Nachtanken; Kaution/Schäden nicht). SQL getrennt.","C","2","live"),
("293","V2a Vermietung: Bußgelder, Halteranfragen, Auslastung","Halteranfragen und Bußgelder wurden von Hand dem Mieter zugeordnet; niemand sah, welches Fahrzeug sich lohnt.","Verleih → Fahrzeugvermietung → Bußgelder: Schreiben erfassen (Behörde, Aktenzeichen, Tatzeit, Frist mit Ampel), die Datenbank findet den Mieter zum Tatzeitpunkt aus tatsächlicher Übergabe und Rückgabe, Fahrer aus dem Vertrag benennen (danach unveränderlich), Text zum Selbstversenden mit eigenem Begleittext, Bearbeitungsgebühr eingefroren als eigene Rechnung (20. Rechnung-aus-Weg, Bußgeld nie auf der Rechnung). Auslastung (Ist-Mietzeit / Kalenderzeit), Ertrag netto und je Miettag, Bußgeld-Vorgänge und Schäden je Fahrzeug; HU-/Wartungs-/Versicherungsfristen aus dem Fuhrpark mit Buchungen über die Frist hinaus. SQL getrennt.","C","1","live"),
("294","V2b Vermietung: Online-Anfrage","Mieter fragten nur per Telefon oder Mail an; es gab keine Seite mit der Mietflotte und ihren Preisen.","Öffentliche Seite „Fahrzeuge mieten“ (an/aus und Google nur durch den Chef): Mietflotte nach Positivliste (nie Kennzeichen, km-Stand, Notiz), Endpreise inkl. 19 % MwSt. bzw. Kleinunternehmer-Hinweis (PAngV), Fahrer-Bedingungen, Preis-Vorschau für den Wunschzeitraum, Formular „Unverbindlich anfragen“ mit Datenschutz-Zustimmung — keine Buchung, keine Zahlung; nach außen nur frei/vergeben. Anfrage mit Nummer MA-Jahr in „📨 Anfragen“, „Als Reservierung übernehmen“ füllt die Buchung, Anfrage-Angaben unveränderlich. Mail an Betrieb und Eingangsbestätigung „unverbindlich“. Verbindliche Online-Buchung erst nach dem Anwalt. SQL getrennt.","C","1","live"),
("V3","Ortung und Telematik über Partner","Ortung von Miet- und Firmenfahrzeugen gibt es nicht.","Anbindung eines Telematik-Partners (Konto des Betriebs, ARGONAUT vermittelt nur); freigeschaltet erst über die Rechts-Freigaben-Zentrale (Zweck, Information, Betriebsrat, Vertrag), Standort nur bei Diebstahl/Rückgabe statt Dauerbeobachtung.","G","1","wartet auf RF1"),
("295","Z1 Zweirad, E-Bike und Dienstrad-Leasing","E-Bike-Händler hatten keine Rahmen-/Akkunummern und keine Dienstrad-Abwicklung mit Leasing-Portalen; Motorrad läuft über den Kfz-Feinschliff.","Werkstatt → Zweirad & E-Bike: Rad-Akte für Bestand und Kundenräder mit Rahmennummer (je Betrieb einmalig), Motor-, Akku-, Display- und Schlüsselnummer, Versicherungskennzeichen beim S-Pedelec; Suche auch nach Rahmen- und Akkunummer; Inspektion mit Fälligkeit und Ampel, Herstellergarantie, Gewährleistungs-Hinweis; Reparatur-Annahme und Inspektion mit Zubehör und Kostengrenze als Auftrag im Werkstatt-Board; Garantiefälle mit Vorgangsnummer des Herstellers. Dienstrad-Leasing: Angebot → im Portal eingereicht → genehmigt (Auftragsnummer, Positionen fest, Rad reserviert) → Übergabe nur mit Rahmennummer, Ausweis und Einweisung (Rad verkauft) → Rechnung an den Leasinggeber (21. Rechnung-aus-Weg); Endpreis fürs Portal gleich gerechnet wie die Rechnung. Keine Portal-Schnittstelle (Status von Hand). SQL getrennt.","C","1","live"),
("296","T1 Trackday, Rennschule, Kartbahn","Motorsport-Veranstalter buchen per Mail und Excel, Haftungsverzichte liegen auf Papier.","Veranstaltungen → Trackday & Kartbahn: Event mit Startgruppen, Startplätzen und Startgeld (volle Gruppe → Warteliste, sperrt die Datenbank), Startnummern je Event einmalig, eigenes Fahrzeug oder Leihfahrzeug aus der Mietflotte (nie doppelt vergeben, nie gleichzeitig vermietet; Mietflotte + Kart und Rennfahrzeug, nie auf der öffentlichen Mietseite). Haftungsverzicht mit eigenem Text des Betriebs (kein Mustertext, fest nach dem ersten Versand) digital über das Signatur-Modul, bei Minderjährigen unterschreibt die sorgeberechtigte Person; Startfreigabe setzt die Datenbank erst mit Unterschrift, Alter, Führerschein und Fahrerbesprechung. Sponsoren, Gäste, Presse, Helfer mit Akkreditierung (Boxengasse nur mit Verzicht), Starter- und Gästeliste zum Drucken, Rechnung je Teilnehmer (22. Rechnung-aus-Weg). Teile mit Laufzeit (Stunden/Runden) je Leihfahrzeug mit Ampel und Tausch-Verlauf. SQL getrennt.","C","1","live"),
("P1","Personenbeförderung: Taxi, Mietwagen mit Fahrer, Bus","Taxi-, Mietwagen- und Busunternehmen haben nur die Branchenseite; Konzessionen, Fahrer-Nachweise und Lenkzeiten fehlen.","Konzessionen und Fristen, Fahrer mit Personenbeförderungsschein, Fahrten und Abrechnung, Lenk- und Ruhezeiten aus Fahrtenschreiber-Dateien — nach dem Anwalt.","G","2","wartet auf Anwalt"),
]))
S.append(("chem","Stufe 3e · Chemie und Shop-Bausteine","Anlass Spezialchemie-Hersteller mit Shop-Wunsch · alles als allgemeine Bausteine für alle Branchen, Chemie als erste Vorlage · Übergabe docs/ARGONAUT-UEBERGABE-CHEMIE-SHOP-11-10-2026.md",[
("314","CH1 Ehrliche Chemie-Texte","Die Website- und SEO-Texte zur chemischen Industrie versprachen zu viel (automatische Gefahrstoff-Doku, Labor, Echtzeit-Bestände, hohe Compliance).","Website- und SEO-Text „chemische Industrie“ nur mit Gebautem: Chargen mit Prüfplan und Rückverfolgung, Gefahrstoffverzeichnis mit Prüf-Ampel, Auftrag, Lager und Rechnung in einem System; ehrlich: ARGONAUT berechnet keine Einstufung. Befund: Nachweise und Gefahrstoffverzeichnis sind seit Paket 194 Grundausstattung jedes Betriebs; Etiketten ist ein Lebensmittel-Modul (LMIV) und bleibt aus dem Industrie-Paket — GHS-Etiketten kommen mit S2/G2b. Kein SQL.","C","1","live"),
("315","S1 Produkt-Dokumente am Artikel","Sicherheitsdatenblätter, Technische Merkblätter, Zertifikate oder Anleitungen ließen sich keinem Artikel zuordnen; im Shop gab es keinen Download.","Artikel-Akte → „📑 Produkt-Dokumente“: PDF je Artikel (bis 20 MB) mit Art (SDB, Merkblatt, Leistungs- und Konformitätserklärung, Spezifikation, Zertifikat, Anleitung, Sonstiges), Sprache (26), Version, Ausgabe, gültig bis; neue Fassung ersetzt die alte derselben Sprache automatisch; Ampel (abgelaufen, läuft in 60 Tagen ab, SDB-Fassung älter als 3 Jahre) und Erinnerung; Download am Produkt im Shop nur für aktuelle, freigegebene, nicht abgelaufene Dokumente (Link direkt aus dem privaten Speicher, 60 Sekunden gültig); Geschäftsleitung: ins Firmen-Wissen fürs Team. Übersicht ERP/Lager → Produkt-Dokumente mit „Shop-Artikel ohne Dokument“. Allgemein für Baustoff, Elektro, Maschinenbau, Lebensmittel. SQL getrennt.","C","1","live"),
("316","S3a Geschäftskunden-Shop: Verwaltung","Der Shop kannte nur Endkunden: keine Kundenpreise, keine Staffeln, keine Gebinde und Mindestmengen; der Verkaufspreis galt im Shop als brutto, der BMEcat-/Datanorm-Import schreibt dort netto hinein.","Shop → „🏢 Geschäftskunden-Shop“: Geschäftskunden aus den Kontakten mit Preisliste, Kauf auf Rechnung, Zahlungsziel (0–90 Tage) und Kreditrahmen; Preislisten mit festen Netto-Preisen in Cent und Staffeln („ab 10“), optional Pauschal-Rabatt (fester Preis geht vor, nie beides); Kundenkonto per geheimem Link (in der Datenbank nur die Prüfsumme, neuer Link macht den alten ungültig, per E-Mail senden); Gebinde und Mindestmenge je Artikel; Preis-Basis des Artikelstamms brutto/netto. Pflegen nur die Geschäftsleitung. SQL getrennt.","C","1","live"),
("317","S3a Geschäftskunden-Shop: Schaufenster und Rechnung","Der Shop erkannte keinen Geschäftskunden; die Rechnung aus dem Shop rechnete netto aus brutto zurück, kannte keinen Kontakt und rechnete steuerfreie Artikel (0 %) mit 19 %; der geschlossene Shop überschrieb seinen Hinweis mit Produkten und Warenkorb.","Kundenlink …/p/<Seite>#konto=… (Schlüssel nur im #-Teil, danach aus der Adresszeile entfernt): Netto-Preise, Staffeln, Konto-Leiste mit Abmelden; Gebinde-Schritte und Mindestmenge für alle Käufer (Server prüft); Zahlart „Auf Rechnung“ nur wenn freigegeben, Kreditrahmen gegen offene Rechnungen und offene Bestellungen; eigene Bestellnummer des Kunden; Rechnung übernimmt Netto-Preise unverändert (Bestell- = Rechnungssumme auf den Cent), Kontakt und Zahlungsziel; 0 % bleibt 0 %; Preis-Basis netto auch für Endkunden; Badge „Geschäftskunde“ in den Bestellungen. Shop bleibt bis zur Freigabe zu. Kein SQL.","C","1","live"),
("318","G2a Gefahrstoffverzeichnis 2.0: Datei, Artikel, Lager","Das Gefahrstoffverzeichnis hatte keine Datei, keine Lagerklasse und keine Verbindung zu Artikel und Lager; neue Stoffe von Mitarbeitern hätten nicht dem Betrieb gehört (Vorgabe war die eigene Kennung).","Je Stoff: verknüpfter Artikel (Bestand aus dem Lager, Vorschlag für den Mengenbereich, Abweichung als Hinweis), Sicherheitsdatenblatt aus den Produkt-Dokumenten des Artikels oder als eigene PDF-Datei (z. B. Reinigungsmittel im Eigenverbrauch), „📄 SDB öffnen“ für alle Beschäftigten über einen 60-Sekunden-Link (GefStoffV), Lagerklasse nach TRGS 510 als Feld (keine Ampel), Lagerplatz, „🔔 Erinnern“ bei SDB älter als 3 Jahre; CSV/Druck mit Lagerklasse und Lagerplatz. Datenbank-Wächter: Artikel und Datei müssen zum Betrieb gehören. SQL getrennt.","C","1","live"),
("319","G2a Gefahrstoffverzeichnis 2.0: QR am Lagerplatz","Am Lagerplatz kam niemand schnell an Sicherheitsdatenblatt und Betriebsanweisung; Mitarbeiter ohne Nachweise-Recht konnten das Verzeichnis gar nicht öffnen.","„🔳 QR-Aushang“: je Lagerplatz ein Druckblatt mit QR-Code und Stoffliste; der QR öffnet die Handy-Ansicht unter Mein Bereich (Login, alle Beschäftigten auch ohne Modul-Recht, nur lesen): Signalwort, Piktogramme, Gefahrenhinweise, Lagerklasse, „📄 Sicherheitsdatenblatt öffnen“, Stand der Betriebsanweisung, Lagerplatz-Filter. Link in Mein Bereich. Kein SQL.","C","1","live"),
("320","Q1 Prüfzertifikat je Charge","Aus dem Prüfplan einer Charge entstand kein Zertifikat für den Kunden (nur ein interner Nachweis mit Lieferanten und Abnehmern); Chargen in Quarantäne ließen sich trotzdem verwenden und ausliefern; Freigabe ohne bestandene Prüfung ging ohne Rückfrage.","„📜 Zertifikat“: Analysenzertifikat oder Abnahmeprüfzeugnis 3.1 (EN 10204, mit Abnahmebeauftragtem) als Druckansicht/PDF, nur bei freigegebener Charge und Prüfung mit allen Merkmalen in der Spezifikation (Server prüft), zeigt nur Produkt, Charge, Prüfergebnisse; Datenbank-Wächter sperrt Verwendung und Auslieferung von Chargen in Quarantäne oder gesperrt; Freigabe ohne bestandene Prüfung nur mit Rückfrage und Vermerk. SQL getrennt.","C","1","live"),
("321","R1 Rezeptur in Prozent: Anteile, Einwaage, Kosten","Die Rezeptur rechnete nur für Lebensmittel (Teigausbeute, Backverlust, Food-Cost); wer mischt oder abfüllt, musste Einwaagen von Hand umrechnen.","Neuer Typ „🧪 Mischung / Abfüllung (Prozent)“: Anteil je Rohstoff in Prozent, eine Zeile „ad 100“ (Rest, z. B. Wasser), Summe mit Ampel; Rohstoff wahlweise aus dem Lager (Einkaufspreis je kg bzw. l übernommen); „⚖ Ansatz umrechnen“ für jede Ansatzgröße – die Einwaagen ergeben durch Rundungsausgleich GENAU den Ansatz; Mengen-Rezept per Knopf in Prozent umrechnen (genau 100 %); Rohstoffkosten je kg, je Standard-Ansatz, nach Verlust, Gebinde je Ansatz und Kosten je Gebinde mit Verpackung; Regel-Auge; Masse und Volumen nie gemischt (Dichte unbekannt); keine GHS-Einstufung. Datenbank-Wächter: verknüpfter Artikel gehört zum Betrieb.","C","1","live"),
("322","R1 Rezeptur in Prozent: Versionen, Tausch, Ansatz → Charge","Rezepturen hatten keine Versionen; ein Rohstoff ließ sich nicht in allen Rezepten auf einmal tauschen; aus einem Ansatz entstand keine Charge mit Rohstoff-Chargen; Mitarbeiter-Speichern ließ alte Zutaten stehen (Zutaten doppelt, weil Mitarbeiter nicht löschen dürfen).","„🗂 Versionen“: Stand festhalten mit Notiz, unveränderbar (wer, wann), Vergleich mit dem aktuellen Stand, Version in den Editor laden; „🔁 Rohstoff in allen Rezepturen tauschen“ (Artikel oder Name, optional neuer Preis, vorher automatisch eine Version je Rezeptur); „🏷 Als Charge anlegen“: Charge in Quarantäne mit Menge nach Verlust, Rohstoffe als Eingang, Rohstoff-Chargen bekommen einen Ausgang (Rückverfolgung vor und zurück, Wächter p320 sperrt gesperrte Rohstoffe); Fertigprodukt-Artikel; „🖨 Ansatzzettel“ für die Waage (Soll, Ist, Rohstoff-Charge, Kürzel); Speichern atomar über eine geprüfte Datenbank-Funktion.","C","1","live"),
("323","S4 Shop mehrsprachig: Sprachen, Übersetzung, Freigabe","Shop und Produkt-Texte gab es nur auf Deutsch; die KI-Übersetzung kannte nur den Baustellen-Ton.","Neue Seite „🌐 Shop mehrsprachig“ mit 24 Sprachen: Produktnamen, Beschreibungen und Shop-Oberfläche als KI-Vorschlag mit wörtlicher Rückübersetzung, bearbeiten, freigeben (nur Geschäftsleitung, Datenbank-Wächter); Englisch-Oberfläche fest eingebaut; Platzhalter-Prüfung; ändert sich der deutsche Text, gilt die Übersetzung als veraltet und der Shop zeigt wieder Deutsch; Sprache erst mit freigegebenen Texten anbietbar; Übersicht der Datenblätter je Sprache; Preise und Zahlen nie übersetzt.","C","1","live"),
("324","Shop mehrsprachig: Sprach-Umschalter im Schaufenster","Der Shop zeigt Kunden noch nur Deutsch, auch wenn Übersetzungen freigegeben sind.","Sprach-Umschalter im Shop (Browser-Sprache als Vorschlag), freigegebene Produkt- und Oberflächen-Texte, Zahlen und Preise im Format der Sprache (immer EUR), Datenblätter in der Kundensprache zuerst, Schrift von rechts für Arabisch und Persisch, Hinweis „Rechtstexte nur auf Deutsch“, Sprache an der Bestellung, Käufer-Bestätigung auf Englisch bei englischer Bestellung. Weitere Währungen und Auslands-Shops erst später (eigenes Rechts- und Steuerthema).","C","1","live"),
("325","S2 Gefahr-Angaben: Auslese aus dem SDB und Bestätigung","Gefahrstoff-Angaben (Piktogramme, Signalwort, H-/P-Sätze, UN-Nummer, UFI) gab es am Shop-Artikel nicht; das Gefahrstoffverzeichnis kannte keine P-Sätze, keinen Wortlaut, keine UN-Nummer.","Neue Seite „⚠️ Gefahr-Angaben im Shop“ je Artikel: KI liest Abschnitt 2.2 und 14 des Sicherheitsdatenblatts als Vorschlag (stuft nichts ein, verwirft unbekannte Codes, meldet fremde Sprache), Übernahme aus dem Gefahrstoffverzeichnis, Pflege von Hand; Bestätigung mit Haken „mit dem SDB verglichen“, wer und wann; Datenbank-Wächter (SDB gehört zum Artikel, Bestätigung nur mit Inhalt und Signalwort); Start-Schalter „gefahrstoffShop“ aus bis R49.","G","1","live"),
("326","Gefahr-Angaben im Shop anzeigen","Bestätigte Gefahr-Angaben erscheinen noch nicht am Produkt und nicht vor dem Bestellknopf.","Anzeige am Produkt (Piktogramme, Signalwort, Gefahrenhinweise, UN-Nummer, UFI) und im Warenkorb vor dem Bestellknopf; nur bestätigte Angaben; Kennzeichnung immer auf Deutsch (Landessprache), alles maskiert; technisch aus bis Anwaltspunkt R49 (Haftung, Art. 48 CLP).","G","1","live"),
("327","S3b Schalter „nur Gewerbekunden“","Jeder kann im Shop bestellen, auch wo Abgabeverbote gelten; Gewerbenachweise der Geschäftskunden wurden nirgends festgehalten.","Gewerbenachweis je Geschäftskunde (USt-IdNr. mit Länder-Muster und deutscher Prüfziffer, Vermerk der BZSt-Bestätigung; Gewerbeanmeldung oder Handelsregisterauszug), „geprüft“ mit wer und wann (Datenbank-Wächter); Schalter „Nur geprüfte Geschäftskunden dürfen bestellen“: Server lehnt sonst ab, Shop zeigt ohne geprüftes Konto keine Warenkorb-Knöpfe und den Hinweis auf ein Kundenkonto; neuer Shop-Text als Zusatz, freigegebene Sprachen bleiben; Start-Schalter „gewerbeNachweis“ aus bis R49.","G","1","live"),
("328","S5 SDB mit der Bestellbestätigung","Das Sicherheitsdatenblatt ging nicht automatisch mit der ersten Lieferung, es gab keinen Versand-Nachweis und keinen Nachversand neuer Fassungen.","Sicherheitsdatenblatt als Anhang der Bestellbestätigung (Fassung in der Bestell-Sprache, sonst Deutsch; nur was die Adresse noch nicht hat; Größen-Deckel); Nachweis je Sendung (wer, welche Fassung, wann, Status) — nur lesbar, schreiben nur der Server; Bestell-Mail an den Betrieb meldet Fehlendes („kein SDB hinterlegt“, „ohne E-Mail: der Lieferung beilegen“); „Aktuelle Fassung an Empfänger der letzten 12 Monate senden“ (REACH Art. 31 Abs. 9, nur Geschäftsleitung); Start-Schalter „sdbVersand“ aus bis R49.","G","1","live"),
("329","G2b Betriebsanweisungs-Entwurf","Betriebsanweisungen wurden außerhalb von ARGONAUT geschrieben.","Je Gefahrstoff eine Betriebsanweisung nach TRGS 555 (Kopf + fünf Abschnitte): „Entwurf füllen“ übernimmt nur vorhandenen Wortlaut (H-/P-Sätze aus den bestätigten Gefahr-Angaben, P-Sätze nach Abschnitt sortiert; sonst H-Codes aus dem Verzeichnis), leere Abschnitte mit Hinweis auf den SDB-Abschnitt — keine eigenen Mustertexte; Druckblatt A4 im orangen Rahmen, ohne Freigabe mit „ENTWURF“; schreiben und freigeben nur die Geschäftsleitung, Beschäftigte lesen und drucken; Änderung nach Freigabe = wieder Entwurf, neue Freigabe = neue Version und Datum im Verzeichnis (Datenbank-Wächter p329); Start-Schalter „betriebsanweisung“ aus bis R49.","G","1","live"),
("330","G2c Zusammenlagerungs-Ampel (TRGS 510)","Ob Stoffe zusammen gelagert werden dürfen, prüfte niemand im System.","Ampel je Lagerplatz im Gefahrstoffverzeichnis nach der Zusammenlagerungstabelle der TRGS 510 (Abschnitt 13): grün erlaubt, gelb nur mit Bedingung Nr. …, rot Separatlagerung; schlechtestes Paar entscheidet, Stoffe ohne Lagerklasse werden gemeldet; keine erfundenen Bedingungstexte, keine Mengenprüfung. Tabelle per Test auf Symmetrie geprüft (441 Felder) — vor dem Einschalten Zelle für Zelle mit dem amtlichen Text abgleichen; Start-Schalter „zusammenlagerung“ aus bis R49.","G","1","live"),
("CH-D1","Chemie-Fachdossier","Für die chemische Industrie gibt es bewusst noch keinen Dossier-Text (Sperr-Gedächtnis, R46).","Dossier nach dem Elektro-Muster, nur Gebautes, sobald R46 geklärt ist.","C","1","wartet auf Anwalt (R46)"),
]))
S.append(("amp","Stufe 3f · Ampel-Beschluss 12.10.","Werkzeug bauen, Betrieb verantwortet sein Branchenrecht · 69 grün bauen, 27 gelb bauen und sperren, keine Branche ausgeschlossen · Reihenfolge: fertig bauen, Testtag, dann Anwalt · Quelle docs/strategie/ARGONAUT-BESCHLUSS-AMPEL-ANWALT-12-10-2026.md",[
('345','A0 Teil 1 Freigabe-Zentrale: Übersicht und Vormerkung','Alle Sperren stehen verstreut im Code (Start-Schalter, Import-Sperren, Bestellstrecke, Zahlung, Kasse, Dossiers); niemand sieht auf einen Blick, was gesperrt ist, warum und welche Anwalt-Frage dahintersteht.','Command Center → „🔐 Freigabe-Zentrale“: alle 25 Schalter und Sperren mit Stand, was aus ist, Anwalt-Frage und Weg zum Öffnen. Freigabe vormerken nur für Start-Schalter und Import-Sperren, nur mit Vermerk (mind. 20 Zeichen) und Datum der Anwalt-Antwort; Ausblenden statt Löschen in drei Schritten (Klick, Rückfrage, Namen eintippen, am Server geprüft). Jede Änderung unveränderbar im Protokoll. Nur Betreiber mit eingerichteter und bestätigter Zwei-Faktor-Anmeldung. Ausbaustufe 1: Vormerkung wirkt noch nicht, Code-Standard bleibt aus. SQL p345: freigabe_schalter, freigabe_protokoll (keine Rechte für Nutzer).','G','1','live'),
('346','A0 Teil 2 Freigabe-Zentrale: Freigabe wirkt','Eine Freigabe in der Zentrale war nur vorgemerkt; jede Öffnung nach dem Anwalt hätte weiter einen Push gebraucht.','Wirksam frei = Schalter im Code an ODER in der Freigabe-Zentrale freigegeben. Alle 11 Start-Schalter und 4 Import-Sperren: 10 Server-Routen, öffentliche Seiten /p und eigene Domains, Menü (Fernhilfe), 10 Seiten im Dashboard, Import-Center und Umzug-Stapel. Server liest mit Service-Rolle, 60 Sekunden Zwischenspeicher, nach jeder Änderung sofort neu; jeder Fehler und jeder unbekannte Schlüssel = gesperrt. Freigeben nur mit Haken „Mitziehen beim Öffnen erledigt“ und Rückfrage; „Wieder sperren“ wirkt genauso schnell; freigegebene Schalter lassen sich nicht ausblenden. Wächter-Test verbietet neue Prüfstellen, die nur den Code lesen.','G','1','live'),
('347','A1 Teil 1 Meine Rechtstexte','ARGONAUT lieferte eigene Vertragsklauseln mit, z. B. im Verwahrprotokoll (Laufzeit 12 Monate mit stillschweigender Verlängerung, Entsorgung nach 14 Tagen) — ohne jeden Prüfhinweis; jeder solche Text müsste vom Anwalt geprüft werden.','Neue Seite Verwaltung → „📜 Meine Rechtstexte“ (nur Chef): eigener Text je Dokument, Gerüst nur mit Überschriften und „[Ihr Text]“ (nicht speicherbar, solange Lücken da sind), Platzhalter {{kunde}} {{betrieb}} {{datum}}, Prüf-Vermerk, jede Änderung eine neue Fassung, frühere Fassungen unveränderbar und auch nach „Entfernen“ belegbar. Verwahrprotokoll nimmt nur noch den Text des Betriebs, sonst Hinweis „keine eigenen Bedingungen hinterlegt“. Katalog mit 7 Texten (Kfz folgt in Teil 2). SQL p347: rechtstext, rechtstext_fassung; Mitarbeiter lesen nur.','C','1','live'),
('348','A1 Teil 2 Kfz-Unterlagen nur mit eigenem Text','Kaufvertrag (Eigentumsvorbehalt, Haftungsausschluss mit Vorbehalten, Verjährungsverkürzung), Reservierung, Zulassungsvollmacht, Probefahrt-Vereinbarung und Ankaufschein enthielten ARGONAUT-Klauseln, nur mit dem Hinweis „vom Anwalt prüfen lassen“.','Alle Kfz-Unterlagen nehmen die Klauseln nur noch aus „Meine Rechtstexte“: Kaufvertrag (Vertragsbedingungen + gesonderte Verjährungs-Vereinbarung mit eigener Unterschrift), Reservierung, Zulassungsvollmacht und Probefahrt-Vereinbarung lassen sich ohne eigenen Text weder drucken noch zur Unterschrift schicken (Hinweis mit Link); Ankaufschein und Werkstattauftrag zeigen nur den Hinweis bzw. keine Bedingungen. Fakten bleiben: Preis, Steuer, Vorschaden, Kilometer, Selbstbeteiligung, gewählte Haftungs-Variante. Neue Platzhalter für die Probefahrt (Selbstbeteiligung, freie Kilometer, Rückgabe).','C','1','live'),
('349','A1 Teil 3 Praxis, Website, KI-Dokumente','Sechs Praxis-Einwilligungen (Gesundheitsangaben, Recall, Ausfallhonorar, Fotos, Fotos für Werbung, Schweigepflicht) waren ARGONAUT-Mustertexte; auf den öffentlichen Kunden-Websites standen interne Hinweise („Grundgerüst aus ARGONAUT OS“, „AGB … ergänzen wir automatisch“) und ein AGB-Abschnitt ohne AGB; KI-erzeugte Arbeitsverträge, Kündigungen, Abmahnungen ohne Prüfhinweis; in der Chat-Karte stand „Agent“.','Praxis: Unterschrift nur mit eigenem Text aus „Meine Rechtstexte“ (Platzhalter Wege, Frist, Betrag, Empfänger), sonst Hinweis und Knopf gesperrt. Website: Datenschutz ohne internen Hinweis, AGB-Abschnitt und Fuß-Link nur mit eigenen AGB (neuer Rechtstext „AGB auf Ihrer Website“). KI-Dokumente mit Rechtswirkung (12 Vorlagen) tragen oben „ENTWURF … vom Anwalt prüfen lassen“, auch in der Chat-Karte; „Agent“ heißt dort „Baustein“.','C','1','live'),
('350','A2 Datei-Sicherung des Speichers','Gesichert wurde nur die Datenbank; die Dateien im Speicher (Belege, Rechnungs-PDFs, Fotos, Dokumente) hatten keine zweite Kopie, eine Wiederherstellung war nie geprobt, ein TOMs-Text fehlte. In der Excel-Datensicherung fehlten 101 Tabellen seit dem 25.09.','Stündlich jede neue oder geänderte Datei verschlüsselt (AES-256-GCM, Schlüssel nur beim Betreiber) an einen zweiten Speicher in Deutschland (S3-kompatibel, Empfehlung Hetzner); gelöschte Dateien bleiben dort 30 Tage. Seite „Datei-Sicherung“ im Command Center mit Ampel, Protokoll, „Jetzt sichern“, echter Probe-Wiederherstellung und Notfall-Wiederherstellung (überschreibt nie). Glocke bei Dauerfehlern, nach 26 Stunden ohne fehlerfreien Lauf und wenn die letzte Probe über 90 Tage her ist. TOMs-Entwurf für den Anwalt. Excel-Sicherung um 91 Tabellen ergänzt, ein Test erzwingt das künftig.','G','1','live'),
('351','A3 Standard-Dossier für 10 Branchen ohne Fachmodule','Hochschulen, Stadtwerke, Netzbetrieb, Flugzeugwartung, Bergbau, Halbleiter, Luft- und Raumfahrt, Verwaltungen, Standesämter und Verkehrsbetriebe hatten nur ein ENTWURF-Dossier; ihr Kategorie-Paket hätte Falsches versprochen (Flugzeugwartung: KFZ-Fachpaket, Verwaltung: Spenden, Verein & Sozial).','Eigenes Standard-Dossier je Branche: nur Grundausstattung, kein Fachpaket, Ablauf eines typischen Vorgangs nur mit gebauten Modulen (am Code geprüft) und eine ehrliche Seite „Dafür passt es – dafür ist es nicht gedacht“ (z. B. kein Personenstandsregister, keine EASA-Freigabebescheinigungen, keine Energieabrechnung). Behörden mit „Anliegen“ statt „Auftrag“. Kein SQL.','C','1','live'),
('352','A4a Fachpaket Bestatter','Für Bestatter gab es nichts außer dem Katalog-Eintrag: keine Sterbefall-Akte, keine Checkliste, kein Kostenvoranschlag mit Friedhofsgebühren, keine Vollmacht; Dienstleistungs-Betriebe hatten nicht einmal den Leistungskatalog.','Sterbefall-Akte mit Nummer je Jahr (verstorbene Person, Auftraggeber, Bestattungsart, Termine, Status), Checkliste je Fall aus der eigenen Checkliste des Betriebs mit eigenen Fristen (ARGONAUT gibt nur Stationen ohne Fristen vor), Kostenvoranschlag aus dem Leistungskatalog mit Auslagen für Dritte getrennt und immer ohne USt (Betrag rechnet die Datenbank), Partner je Fall (aus Netzwerk, Kontakten oder frei), Vollmacht nur mit eigenem Text aus „Meine Rechtstexte“. Bestatter bekommen Modul Bestattung + Leistungskatalog. SQL p352.','C','1','live'),
('353','A4b Teil 1 Bewachung: Wachbuch und Kontrollgänge','Für Wachdienst, Objektschutz, Veranstaltungssicherheit und Werttransport gab es nichts: kein Wachbuch, keine Wächterkontrolle, kein Nachweis für den Auftraggeber.','Kontrollpunkte je Objekt mit QR-Aufkleber (Code vergibt die Datenbank), Rundgang per Handy-Scan oder Code eintippen mit Serverzeit, Standort nur freiwillig; Wachbuch nur anhängbar (Meldung, Vorkommnis, Übergabe, Schaden, Polizei/Feuerwehr/Rettung), Korrektur nur als Nachtrag — auch der Chef ändert und löscht nichts; Nachweis je Zeitraum mit erreichten und fehlenden Punkten, ohne Standort. Bewachungsbetriebe bekommen Modul Bewachung + Objektzeiten. SQL p353.','C','1','live'),
('354','A4b Teil 2 Bewachung: Nachweise und Dienstplan','Unterrichtung und Sachkunde nach § 34a GewO, Bewacher-ID und die Erlaubnis des Betriebs standen nirgends; Wachpersonen ließen sich ohne jede Prüfung einplanen.','Pflichtangaben des Betriebs (Erlaubnis § 34a GewO, Bewacherregister-Nummer) mit rotem Hinweis, bis sie eingetragen sind, und auf Dienstplan und Nachweis; Nachweise je Wachperson (Unterrichtung, Sachkunde, Bewacher-ID) in der Dispo-Qualifikationsliste; Dienstplan je Objekt mit Vorgaben je Objekt, Warnung bei fehlendem Nachweis (einplanen nur mit Bestätigung, Vermerk bleibt), Doppelbuchung sperrt die Datenbank, Druck je Woche. SQL p354.','C','1','live'),
('355','A4c Teil 1 Entsorgung: Container-Dienst und Wiegeschein','Container-Dienste, Entsorger, Schrott- und Recyclinghöfe hatten keinen Containerbestand, keine Stell-/Abholaufträge und keinen Wiegeschein.','Eigene Liste der Abfallschlüssel (6 Ziffern, Sternchen = gefährlich, kein amtlicher Katalog), Containerbestand mit Stand Hof/Kunde/voll/Reparatur und Standzeit, Aufträge Stellen/Tauschen/Abholen je Tag mit Tagesliste für die Fahrer — beim Erledigen setzt die Datenbank die Container um (gesperrt gegen Doppel-Stellen); Wiegeschein mit Nummer je Jahr, Wägezeiten und Netto von der Datenbank, nach Abschluss unveränderbar, Storno nur Chef mit Grund, Druck. Modul Entsorgung für 7 Branchen. SQL p355.','C','1','live'),
('356','A4c Teil 2 Entsorgung: Abfallregister und ADR-Beförderungspapier','Annahmen und Abgaben standen in keinem Register; Beförderungspapiere für Gefahrgut und die 1000-Punkte-Rechnung wurden von Hand geschrieben.','Abfallregister nur anhängbar (Storno nur Chef mit Grund), je Wiegeschein ein Eintrag per Klick übernommen, Erzeuger/Beförderer/Entsorger mit Nummern, Nachweis- und Begleitschein-Nummer, Verfahren R/D, Druck und CSV für die Behörde; ADR-Beförderungspapier Inland mit Zeile nach 5.4.1.1.1 (ABFALL, UMWELTGEFÄHRDEND), 1000-Punkte-Rechnung nach 1.1.3.6, Ausstellen erst nach Freigabe „adrPapier" (R58), bis dahin ENTWURF. eANV bleibt beim Betrieb. SQL p356.','C','1','live'),
('357','A4d Fachpaket Tierhaltung: Arzneimittel-Bestandsbuch','Höfe mit Nutztieren führten Erwerb und Anwendung von Tierarzneimitteln und die Wartezeiten außerhalb des Systems.','Bestandsbuch nur anhängbar (Storno nur Chef mit Grund, Zeit und Name vom Server): Erwerb mit Charge, Zulassungs- und Beleg-Nr., Verfall; Anwendung je Tiergruppe aus dem Tierbestand mit Kennzeichnung, Beleg-Nr., Menge, Behandlung von/bis, Wartezeiten Fleisch/Milch/Eier — „frei ab" rechnet die Datenbank; Überblick gesperrte Gruppen, Fristen (Wartezeit-Ende, Antibiotika-Mitteilung 14.07./14.01., Verfall), Halbjahres-Übersicht Antibiotika mit CSV, Druck je Zeitraum/Gruppe. Keine Übermittlung an HIT. SQL p357.','C','1','live'),
('358','VK1 Teil 1 Verkaufsteam: Zuständige, Funktionen, freie Setter','Leads gehörten nur dem Betrieb, nie einer Person: niemand war zuständig, keine „Meine"-Ansicht, jeder Mitarbeiter sah alle Leads und Deals.','Setter und Closer je Lead (Auswahl, „Ich übernehme"), Funktion je Person Setter/Closer/Teamleitung, Filter Meine/Ohne Zuständige/je Person, Seite Verkaufsteam mit Übersicht je Person. „frei": sieht nur eigene Leads, keine Deals, keinen Angebotsentwurf, ändert keine Zuständigen — per Datenbank-Regel. Fund nebenbei: Arznei-Menüeintrag P357 bog den Modul-Pfad um, repariert + Wächter-Test. SQL p358.','C','1','live'),
("A0","Freigabe-Zentrale im Command Center","Alle Sperren stehen als Schalter im Code; jede Freigabe nach dem Anwalt braucht einen Push, und niemand sieht auf einen Blick, was gesperrt ist und warum.","Gebaut in Paket 345 (Übersicht, Freigabe mit Vermerk, Ausblenden in drei Schritten, Protokoll) und Paket 346 (Freigabe wirkt: Server und Seiten lesen Code ODER Zentrale, jeder Fehler = gesperrt, Haken „Mitziehen erledigt“ Pflicht).","G","0","live"),
("A1","Vorlagen-Prinzip","ARGONAUT liefert eigene Mustertexte (Kfz-Kaufvertrag, Probefahrt, VOB-Schreiben, Praxis, WEG …); jeder davon müsste einzeln vom Anwalt geprüft werden.","Gebaut in Paket 347 („Meine Rechtstexte“, Verwahrprotokoll), 348 (alle Kfz-Unterlagen nur mit eigenem Text) und 349 (Praxis-Einwilligungen, Website-AGB nur mit eigenem Text, keine internen Hinweise öffentlich, KI-Dokumente mit Rechtswirkung als ENTWURF).","C","0","live"),
("A2","Datei-Sicherung des Speichers","Gesichert wird nur die Datenbank; Dateien im Speicher (Belege, Fotos, Dokumente) haben keine eigene Sicherung – die TOMs müssen stimmen.","Gebaut in Paket 350 (stündlich verschlüsselt an einen zweiten Speicher, Probe- und Notfall-Wiederherstellung, TOMs-Entwurf). Wirkt, sobald Martin den Speicher bei Hetzner angelegt, die sechs Werte in Vercel eingetragen und die erste Probe-Wiederherstellung gedrückt hat.","G","0","wartet auf Martin"),
("A3","Standard-Dossier für 10 Branchen ohne Fachmodule","Behörden, Standesamt, Stadtwerke, Netzbetrieb, Uni, Verkehrsbetriebe, Bergbau, Halbleiter, Luft- und Raumfahrt, Flugzeugwartung waren als „nicht bauen“ markiert.","Gebaut in Paket 351: Standard-Dossier mit Grundausstattung, ohne Fachpaket, mit Seite „Dafür ist es nicht gedacht“. Fachmodule nur, wenn ein echter Kunde fragt.","C","0","live"),
("A4a","Fachpaket Bestatter","Kein Gerüst für Sterbefälle.","Gebaut in Paket 352: Sterbefall-Akte, Checkliste mit eigenen Fristen, Kostenvoranschlag aus dem Leistungskatalog mit Auslagen ohne USt (Steuerberater-Frage R56), Vollmacht nur mit eigenem Text, Partner je Fall. Später bei Bedarf: Rechnung aus dem Sterbefall (nach Steuerberater) und Beauftragung über das Netzwerk mit Datenweitergabe (nach Anwalt).","C","0","live"),
("A4b","Fachpaket Bewachung (§ 34a)","Wachdienst, Objektschutz, Veranstaltungssicherheit und Werttransport haben nur den Standard.","Gebaut in Paket 353 und 354: Wachbuch (nur anhängbar), Kontrollgänge mit QR-Kontrollpunkten, Nachweis für den Auftraggeber, Pflichtangaben des Betriebs, Nachweise der Wachpersonen (Unterrichtung, Sachkunde, Bewacher-ID), Dienstplan je Objekt mit Warnung bei fehlendem Nachweis. Meldungen ans Bewacherregister bleiben beim Betrieb (R57).","C","0","live"),
("A4c","Fachpaket Abfall, Entsorgung, Gefahrgut","Entsorger und Gefahrguttransporte führen Nachweise außerhalb des Systems.","Gebaut in Paket 355 und 356: Container-Dienst, Wiegeschein, Abfallregister (nur anhängbar, Druck/CSV), ADR-Beförderungspapier Inland mit 1000-Punkte-Rechnung (Ausstellen nach Freigabe R58). eANV-Übermittlung bleibt beim Betrieb.","C","0","live"),
("A4d","Fachpaket Tierhaltung","Bestandsbuch und Arzneimittel-Nachweise fehlen für Höfe.","Gebaut in Paket 357: Arzneimittel-Bestandsbuch (Erwerb, Anwendung je Tiergruppe mit Wartezeiten, „frei ab“ von der Datenbank), Fristen, Antibiotika-Halbjahresübersicht, Druck. Baut auf Tierbestand auf.","C","0","live"),
("A4e","Fachpaket Lebensmittel-Herstellung","Brauerei, Molkerei, Mühle haben kein Herstellungs-Gerüst außerhalb von HACCP.","Chargen und Rezeptur aus der Manufaktur (BV3a) für Herstellung im Großen; Brauerei mit Sudprotokoll.","C","1","offen"),
("A4f","Fachpaket Weinbau","Winzer haben nur den Standard.","Weinbergs- und Lesebuch, Kellerbuch, Chargen je Jahrgang.","C","1","offen"),
("A4g","Fachpaket Vermittlung","Personal- und Haushaltshilfe-Vermittlung ohne Vermittlungs-Ablauf.","Bewerber und Stellen, Vermittlungsvorgang, Vermittlungsvertrag als eigene Vorlage des Betriebs; keine Bewerber-KI.","C","1","offen"),
("A4h","Fachpaket Drohnen und Flugschule","Kein Gerüst für Einsätze und Ausbildung.","Einsatzbuch, Nachweise und Fristen der Piloten, Geräte-Wartung über das Wartungsmodul.","C","1","offen"),
("A4i","Fachpaket Bäder, Therme, Sauna","Nur Branchenseiten; die Webseite verspricht Auslastung in Echtzeit und Kasse/Sauna/Gastro in einem System, beides gibt es nicht.","Eintritt und Tarife, Saison- und Wertkarten, Besucherzählung, Wasserqualität mit Messwerten, Badeaufsicht mit Nachweisen und Plan, Aufgussplan; Texte der Branchenseiten auf Gebautes zurückschneiden. Kasse erst mit TSE-Partner.","C","3","offen"),
("A5","Schutz-Paket für besondere Daten","27 Branchen mit Gesundheits-, Kinder- oder Religionsdaten (Kita, Schule, Senioren, Soziales, Kirchen, Hausnotruf) haben kein geschütztes Gerüst.","Verschlüsselte Klientenakte nach dem Muster des Praxis-Pakets (Verschlüsselung, Freigabe je Mitarbeiter, Zugriffsprotokoll); technisch gesperrt bis der AV-Vertrag mit TOMs geprüft ist, Freigabe in der Freigabe-Zentrale.","G","3","offen"),
("A6","Dossiertexte für 69 grüne und 27 gelbe Branchen","96 Branchen ohne Fachdossier, obwohl das Werkzeug gebaut werden darf.","Texte in Wellen wie B11c, nur Gebautes, keine Rechtsversprechen; gelbe gesperrt bis zur Freigabe.","C","11","offen"),
("A7","Dossiertexte für die 206 gesperrten Branchen (optional)","Handel, Gastro, Sport, Lebensmittel, Gesundheit, Recht, Tiere ohne Dossier.","Vorschreiben und gesperrt lassen, bis Kasse (TSE-Partner), Shop (eigene Rechtstexte) bzw. AV-Vertrag frei sind.","C","23","wartet auf Kasse und Shop (optional)"),
]))
S.append(("acad",'Stufe 3g · Academy: Ausbildung per Video','Neu seit 13.10.2026 · Beschluss im Gespräch mit Martin: On-the-Job-Ausbildung per kurzen Videos, Untertitel in jeder Sprache, Speicher bei Hetzner · Reihenfolge noch nicht festgelegt (A3 bleibt der nächste Schritt) · Anwalt-Punkte beim Bau anlegen: Einwilligung der Mitarbeiter im Video, Speicherfrist und Löschung in den AGB, AVV Hetzner und Untertitel-Anbieter',[
  ('AK1', 'Academy-Fundament: Kurse, Lektionen, Fortschritt, Optik', 'Korrigiert 13.10. nach Code-Prüfung: Player, Fortschritt mit Wiedereinstieg, Medaillen, Chef-Übersicht und eigene Kurse mit Pflicht-Haken gibt es seit August. Es fehlt: Ein Kurs ist genau ein Video – keine Abschnitte und Lektionen, kein Lesezeichen, keine Rückmeldung je Lektion, Optik nicht auf Lernplattform-Niveau.', 'Leerer Ausbildungsort je Betrieb, den der Betrieb selbst füllt (Baustelle, Werkstatt, Lager). Kurs → Abschnitte → Lektionen (Sekunden bis ca. 13 Minuten), Schritt für Schritt von Anfang bis Ende. Fortschrittsring, Häkchen, „Lektion abschließen“, „Nächste Lektion“, Lesezeichen, Rückmeldung je Lektion. Guter Player (Geschwindigkeit, Vollbild), fürs Handy auf der Baustelle gebaut. Chef legt an, Mitarbeiter schauen; Fortschritt je Mitarbeiter für den Chef sichtbar. Maßstab Bedienung und Optik einer führenden Lernplattform. Software-Erklärung bleibt beim Guide. Vorhandenes wird erweitert, nicht neu gebaut.', 'C', '2', 'offen'),
  ('AK2', 'Video-Speicher bei Hetzner mit Geheim-Links', 'Videos würden heute im Supabase-Speicher landen – teuer bei großen Dateien und viel Abruf. Supabase-Regeln (Betrieb A sieht nie B) gelten bei einem fremden Speicher nicht automatisch.', 'Supabase bleibt das Gehirn (Datenbank, Login, Rechte), Hetzner Object Storage (Deutschland) wird das Lager für schwere Dateien. Upload direkt vom Handy zu Hetzner, Signatur aus P350 (SigV4) wiederverwenden. In der Datenbank nur der Verweis. Abspielen nur über kurzlebige Geheim-Links, die an EINER zentralen Stelle im Code entstehen, nachdem der Betrieb geprüft ist. Von Anfang an so angelegt, dass später mehrere Ablage-Fächer (Grenze 750 Abrufe/s je Fach) und ein CDN davor nur eine Erweiterung sind. Speicher-Kontingent je Betrieb über den vorhandenen Speicher-Wächter, Academy als kostenpflichtiger Zusatz.', 'G', '2', 'offen'),
  ('AK3', 'Aufnahme vom Handy: Gesicht oder Objekt umschalten', 'Meister soll sich selbst und das Objekt zeigen (vor dem Haus, Blick aufs Dach). Im Handy-Browser lassen sich Front- und Heckkamera nicht gleichzeitig öffnen.', 'Aufnahme direkt in ARGONAUT mit großem Umschalt-Knopf Gesicht/Objekt während der Aufnahme, wahlweise nur eine Kamera. Fertige „Dual-Aufnahmen“ aus der Handy-Kamera (z. B. Samsung) einfach hochladen. Echtes Bild-in-Bild live (Gesicht im Kreis, Objekt groß) erst mit eigener App – siehe AK7.', 'C', '1', 'offen'),
  ('AK4', 'Videos automatisch verkleinern (Hostinger-Server)', 'Handy-Videos sind roh riesig (4K mehrere hundert MB je Minute) und ruckeln bei schlechtem Netz auf der Baustelle.', 'Nach dem Hochladen verkleinert der vorhandene Hostinger-Server die Videos (720p/1080p, Vorschaubild), später Abspielen in Stufen, das sich der Verbindung anpasst. Original wird danach gelöscht. Martin: Zugang am Server freigeben bzw. ffmpeg-Dienst einrichten lassen.', 'G', '2', 'wartet auf Martin'),
  ('AK5', 'Untertitel in jeder Sprache', 'Gemischte Teams auf der Baustelle verstehen deutsche Erklärungen nicht immer; niemand traut sich nachzufragen.', 'Einmal je Video: Sprache-zu-Text ergibt deutschen Untertitel, der Meister korrigiert Fachbegriffe (Kehle, Ortgang), danach Übersetzung in die 24 vorhandenen Sprachen. Im Player wählt jeder seine Untertitel-Sprache. Kosten einmalig je Video, über kiFetch protokolliert und weiterberechnet. Wartet auf Wahl des Sprache-zu-Text-Anbieters samt AVV.', 'G', '2', 'wartet auf Anbieter-Wahl'),
  ('AK6', 'Content-Archiv für Social Media mit Speicherfrist', 'Social-Media-Videos und Bilder werden nach dem Posten nicht dauerhaft vorgehalten; guter Content geht verloren statt wiederverwendet zu werden.', 'Academy- und Social-Media-Inhalte liegen gemeinsam im Hetzner-Archiv und sind wiederverwendbar. Speicherfrist 6–12 Monate, Abrechnung nach Größe (Kontingent-Pakete) statt pro Video. Nie still löschen: Erinnerung 30 Tage vorher („verlängern oder herunterladen“), danach Schonfrist. Automatisches Löschen bleibt aus, bis die AGB-Regel vom Anwalt bestätigt ist.', 'G', '2', 'offen'),
  ('AK7', 'Echtes Bild-in-Bild mit eigener App', 'Gleichzeitige Front- und Heckkamera geht nur in einer echten App, nicht im Browser.', 'Später mit eigener ARGONAUT-App: Gesicht im Kreis, Objekt groß, an- und ausschaltbar. Nicht in den offenen Pushes gezählt.', 'C', '–', 'wartet auf App (später)'),
]))
S_VK=("vk",'Stufe 3h · Verkaufsteam: Setter, Closer, Agenturen','Neu seit 13.10.2026 · Beschluss mit Martin: alles bauen · als allgemeines Modul für jeden Betrieb mit Innen- und Außendienst, die Setter-/Closer-Agentur ist die erste Branchenvorlage · abgeglichen mit führenden Vertriebs-Systemen (Telefon-CRM, Agentur-Plattform, Termin-Routing, Gesprächsanalyse) · Bestand im Code 13.10. geprüft · Reihenfolge-Empfehlung: nach A4d zuerst VK1, VK4, VK11 (die Anruf-Sitzung nutzt Martin selbst für seine Kaltanrufe) · Anwalt-Punkte beim Bau anlegen · bewusst NICHT gebaut: Mail-Öffnungs-Tracking (DSGVO), LinkedIn-Auslesen, Massen-Kaltmails (UWG), Wählautomat mit stillen Anrufen',[
  ('VK1','Fundament: Zuständige, Rollen, eigene Pipelines','Leads und Deals gehören nur dem Betrieb, nie einer Person: niemand ist zuständig, keine Ansicht „meine Leads“. Die Pipeline hat 6 fest eingebaute Stufen, nur eine Pipeline je Betrieb.','Zuständig-Feld an Leads und Deals (Setter und Closer getrennt), Funktion je Mitarbeiter Setter / Closer / Teamleitung, „Meine“-Ansichten. Eigene Pipelines mit eigenen Stufen (z. B. Neukunden, Bestandskunden, je Auftraggeber), Vorbelegung bleibt. Freie Setter sehen nur ihre Leads, nie Geldzahlen des Betriebs.','C','1','nächster'),
  ('VK2','Qualifizierung und Übergabe Setter → Closer','Der Setter hat nur Freitext. Der Closer geht blind ins Gespräch; Leads, die nicht passen, bleiben ewig offen.','Qualifizierungsbogen je Angebot (Budget, Entscheider, Bedarf, Zeitpunkt, eigene Fragen), Übergabe mit Notiz und Glocke an den Closer, Spickzettel vor dem Gespräch auf einer Seite. „Passt nicht“ mit Grund schließt den Lead sauber ab und zählt in der Auswertung.','C','1','offen'),
  ('VK3','Termin-Verteilung auf Closer','Online-Buchung kennt Verfügbarkeiten je Mitarbeiter, verteilt aber nicht: kein Reihum, keine Regeln, kein Übertragen.','Verteilung reihum, nach freier Zeit oder nach Regeln aus den Antworten (z. B. Budget über 10.000 € an erfahrene Closer). Termin an Kollegen übertragen, wenn jemand ausfällt. Kalender je Closer, Doppelbuchung wie gehabt per Datenbank verhindert.','C','2','offen'),
  ('VK4','Anruf-Sitzung mit Ergebnis-Codes','Anrufe werden nur gezählt. Keine Tagesliste, kein „nächster Kontakt“, keine Rückruf-Planung; niemand sieht, wie schnell ein neuer Lead angerufen wurde.','Tages-Warteschlange aus gespeicherten Listen, Anruf per Klick, danach Ergebnis-Code (nicht erreicht, Mailbox, Rückruf, kein Interesse, Termin), automatisch der nächste Kontakt. Versuche je Kontakt, Rückruf-Wiedervorlage, Uhr „Zeit bis zum ersten Anruf“ mit Glocke bei neuen Leads. Läuft ohne Telefonanlage; mit VK20 wählt sie selbst.','C','2','offen'),
  ('VK5','Show-up-Maschine','Erinnerung nur am Vortag, keine 1-Stunden-Erinnerung, Termine kennen kein „nicht erschienen“.','Bestätigung sofort, Erinnerung 24 Std. und 1 Std. vorher (Mail, WhatsApp-Vorlage), Status „nicht erschienen“ an Terminen, danach Rückhol-Folge mit neuem Buchungslink. Show-Rate fließt in VK7.','C','1','offen'),
  ('VK6','Gesprächsergebnis und Übergabe an die Umsetzung','Nach dem Verkaufsgespräch wird nichts strukturiert festgehalten: Angebot gemacht? Einwand? Wie viel vereinbart, wie viel angezahlt?','Kurzes Ergebnis-Formular nach jedem Gespräch (erschienen, angeboten, abgeschlossen, vereinbart, Anzahlung, Haupteinwand). Daraus per Klick Angebot oder Auftrag, danach Übergabe an Projekt bzw. Kundenportal mit Willkommens-Mail.','C','1','offen'),
  ('VK7','Kennzahlen-Board und Rangliste','Kein Board je Person. Lead-Quelle ist Freitext, Werbe-Kennzeichen (UTM) landen nur in der Website-Analyse, nicht am Lead. Liegengebliebene Deals fallen niemandem auf.','Je Person und Team: Anrufe, Gespräche, gebuchte Termine, Show-Rate, Abschlussquote, vereinbart gegen tatsächlich eingegangen, Zeit bis zum ersten Kontakt. Quelle und UTM fest am Lead, Auswertung je Kanal und je Closer. Rangliste, Stillstand-Warnung für Deals ohne Bewegung. Alles visuell.','C','2','offen'),
  ('VK8','Ziele, Prognose, Tagesabschluss','Keine Monatsziele je Person, Prognose nur für den ganzen Betrieb, Tagesberichte laufen über WhatsApp-Gruppen.','Ziele je Person und Monat mit Fortschritt, gewichtete Prognose je Closer. Tagesabschluss-Bericht erstellt sich aus den Zahlen selbst, plus eine Zeile Freitext; Wochenbericht an die Teamleitung.','C','1','offen'),
  ('VK9','Gesprächsleitfäden und Einwand-Bibliothek','Es gibt nur die Fragevorlagen des Website-Setters, keine Leitfäden für Menschen am Telefon.','Leitfäden je Angebot (bzw. je Auftraggeber), Einwände mit bewährten Antworten, während der Anruf-Sitzung einblendbar. Häufigste Einwände aus VK6 werden gezählt und angezeigt.','C','1','offen'),
  ('VK10','Lead-Bewertung automatisch','leads.score wird angezeigt und sortiert, aber nirgends berechnet.','Bewertung nach festen Regeln ohne KI (Quelle, Antworten aus VK2, Aktivität, Alter), nachvollziehbar je Punkt. VK3 kann danach verteilen.','C','1','offen'),
  ('VK11','Anruf-Sperrliste und Erlaubnis-Ampel','Die Werbe-Sperre kennt nur E-Mail-Adressen. Vor einem Anruf warnt nichts, ob er erlaubt ist.','Sperrliste für Telefonnummern, Werbewiderspruch gilt auch fürs Telefon. Ampel vor jedem Anruf: Verbraucher ohne Einwilligung rot, Gewerbe gelb mit Pflichtfeld „Grund für mutmaßliches Interesse“, Bestandskunde grün; Nachweis wird gespeichert. Wortlaut der Hinweise prüft der Anwalt.','G','1','offen'),
  ('VK12','Branchenvorlage Setter-/Closer-Agentur','Ein neuer Vertriebsbetrieb müsste Stufen, Bögen, Leitfäden und Abläufe selbst anlegen.','Vorlage mit einem Klick: Pipelines, Qualifizierungsbogen, Leitfäden, Erinnerungen, Ziele vorbelegt. Dazu Vorlagen „Handwerk: Büro vergibt Termine, Meister verkauft vor Ort“ und „Innendienst / Außendienst“.','C','1','offen'),
  ('VK13','Außendienst-Besuche','Verkäufer vor Ort planen Besuche außerhalb des Systems; Besuchsberichte fehlen.','Tour-Modul für Verkaufsbesuche nutzen: Besuchsplan, Route, Besuchsbericht am Handy (auch per Sprache), Ergebnis wie VK6.','C','1','offen'),
  ('VK14','Provisionen Setter und Closer','lib/provision.ts rechnet nur für Partner aus gewonnenen Deals: kein Setter-/Closer-Anteil, Basis ist der Deal statt des eingegangenen Geldes, keine Rückforderung.','Anteile je Rolle, Basis wahlweise eingegangenes Geld, Rückforderung bei Storno oder Rücklastschrift, Monatslauf mit Freigabe durch den Chef, Gutschrift für freie Mitarbeiter. Vorbauen, aus bis Anwalt (Scheinselbstständigkeit, Gutschrift nach UStG).','G','2','offen'),
  ('VK15','Agentur-Modus: mehrere Auftraggeber','Die Agentur-Seite ist ein Branchenmodul (Retainer, Zeiten). Eine Vertriebsagentur kann nicht sauber getrennt für Auftraggeber A, B, C verkaufen.','Auftraggeber im Agentur-Betrieb: eigene Pipelines, Leitfäden, Ziele und Provisionssätze je Auftraggeber; Bericht für den Auftraggeber über einen Portal-Link. Echte Unterkonten (zwischen Betrieben umschalten) erst später, weil sie die Mandantentrennung berühren. Vorbauen, aus bis Anwalt (AVV Agentur als Auftragsverarbeiter).','G','2','offen'),
  ('VK16','Ratenzahlung bei hohen Beträgen','Abschläge gibt es, aber keine Zahlungspläne aus einem Abschluss.','Zahlungsplan aus dem Gesprächsergebnis, Raten per SEPA, Provision je eingegangener Rate, Mahnung nur bei echtem Ausfall. Kern-Geld: gemeinsam. Aus bis Anwalt (Teilzahlung bei Verbrauchern).','G','1','offen'),
  ('VK17','Gesprächsaufnahme mit KI-Auswertung','Kein Gesprächsmitschnitt, kein Coaching aus echten Gesprächen.','Aufnahme hochladen oder aus VK20: Abschrift, Zusammenfassung, erkannte Einwände, Coaching-Hinweise, Entwurf der Nachfass-Mail; über kiFetch protokolliert. Nur mit nachgewiesener Einwilligung beider Seiten. Aus bis Anwalt (Strafbarkeit bei Aufnahme ohne Einwilligung, AI-Act-Hinweis).','G','2','offen'),
  ('VK18','Persönliche Nachfass-Folgen','Nachfass-Ketten laufen nur für Leads der Website, nicht für einzelne Kontakte im Verkauf.','Folgen aus Mail und WhatsApp je Kontakt, stoppen automatisch bei Antwort oder Termin. Nur an Bestandskunden und mit Einwilligung, geprüft über die Werbe-Erlaubnis. Aus bis Anwalt.','G','1','offen'),
  ('VK19','Abschluss digital unterschreiben','Die eigene Signatur-Strecke gibt es (Kfz, Motorsport), aber nicht aus dem Verkaufsgespräch heraus.','Aus VK6 per Klick Auftrag mit eigenem Rechtstext zur Unterschrift senden, bei Verbrauchern mit Widerrufsbelehrung. Aus bis Anwalt (Fernabsatz).','G','1','offen'),
  ('VK20','Telefonanlage anbinden','Kein Telefon-Anbieter im Code, kein Anrufprotokoll, keine SMS.','Partner (z. B. sipgate, Twilio): Anruf aus ARGONAUT, automatisches Protokoll, Mailbox-Nachricht per Klick, Wählen aus der Anruf-Sitzung, Mithören und Einflüstern für die Teamleitung, SMS. Kunde bringt sein Konto.','G','2','wartet auf Partner'),
  ('VK21','Verpasster Anruf → sofort Antwort','Ruft ein Interessent an und niemand hebt ab, ist er meist verloren.','Nach verpasstem Anruf geht innerhalb einer Minute eine Nachricht mit Rückruf-Angebot und Buchungslink raus, Glocke an den Zuständigen. Braucht VK20.','C','1','wartet auf VK20'),
  ('VK22','KI-Telefon-Setter','Außerhalb der Bürozeiten nimmt niemand Anfragen am Telefon an.','Mit dem Telefon-Partner (Retell oder Vapi): eingehende Anrufe annehmen, qualifizieren, Termin buchen, Übergabe wie VK2. Ausgehend nur bei Einwilligung. Hinweis „Sie sprechen mit einer KI“ Pflicht. Wartet auf Partner und Anwalt.','G','2','wartet auf Partner'),
  ('VK23','Direktnachrichten-Postfach','Nachrichten aus Instagram und Facebook laufen am System vorbei.','Gemeinsames Postfach über die Meta-Schnittstelle, Nachricht wird Lead mit Zuständigem. LinkedIn bietet keine offene Schnittstelle, daher nicht.','C','1','wartet auf App-Prüfung'),
  ('VK24','Firmendaten ergänzen','Setter suchen Branche, Größe und Geschäftsführer von Hand.','Partner-Anbindung (Handelsregister-Daten) ergänzt Firmenkontakte per Klick, Kosten über das Konto des Kunden.','C','1','wartet auf Partner'),
])
S.append(S_VK)
S_CO=("co",'Stufe 3i · Live-Raum, Team-Meetings und Coaching','Neu seit 13.10.2026 · Beschluss mit Martin: komplett bauen · Live-Raum als allgemeiner Baustein für alle Branchen (Team-Meeting, Sofort-Besprechung von der Baustelle, Kunden-Videotermin, Live-Kurs) · eigener Videoserver mit freier Software bei Hetzner in Deutschland statt US-Anbieter; große Webinare mit Hunderten Zuschauern weiter per Link oder Livestream · Coaching abgeglichen mit führenden Community-, Kurs- und 1:1-Coaching-Plattformen · Bestand im Code 13.10. geprüft: Webinar nur mit externem Zoom-/Teams-Link, kein Login für Endkunden, keine Klientenakte · Anwalt-Punkte beim Bau anlegen',[
  ('LV0','Videoserver bei Hetzner einrichten','Es gibt keinen eigenen Videoserver; Live läuft nur über fremde Anbieter per Link.','Martin bucht einen Server bei Hetzner (Deutschland), Claude liefert die Schritt-für-Schritt-Anleitung (freie Software Jitsi bzw. BigBlueButton für Kurse mit Whiteboard und Gruppenräumen), Belastungstest vor dem Start: wie viele Teilnehmer gleichzeitig.','M','0','wartet auf Martin'),
  ('LV1','Live-Raum: Fundament','Kein Videoraum in ARGONAUT, keine Einladung nur für Berechtigte.','Videoraum direkt in ARGONAUT (Browser und Handy, keine Installation). Räume je Team, Projekt, Kurs oder Termin; Zutritt nur mit kurzlebigem Geheim-Link, der an EINER zentralen Stelle nach Prüfung von Betrieb und Recht entsteht. Gäste von außen (Planer, Kunde) per Einladungslink mit Warteraum, der Gastgeber lässt herein. Bildschirm teilen, Hand heben, Chat im Raum. Glocke und Mail bei Einladung.','G','2','offen'),
  ('LV2','Team-Meetings und Besprechungen','Team-Besprechungen laufen über fremde Programme; Ergebnisse und Aufgaben landen nirgends im System.','Besprechung planen (einmalig oder wiederkehrend) mit Einladung aus dem Team-Kalender, Raum je Team oder Standort. Danach Protokoll mit Beschlüssen und Aufgaben (an Personen mit Frist) direkt in ARGONAUT, Anwesenheit wird festgehalten.','C','1','offen'),
  ('LV3','Sofort-Besprechung von der Baustelle','Läuft auf der Baustelle etwas schief, telefonieren Monteur, Vorarbeiter, Bauleiter und Planer nacheinander; niemand sieht das Problem, und es wird nichts festgehalten.','Knopf „Sofort-Besprechung“ in Projekt, Bautagebuch, Einsatz oder Auftrag: Glocke an die Beteiligten (Vorarbeiter, Bauleitung, Chef), externer Planer oder Kunde per Link. Monteur zeigt das Problem mit der Handy-Rückkamera; Standbilder landen per Klick im Bautagebuch bzw. am Projekt. Ergebnis als Aufgabe oder Mangel mit Zuständigem, Dauer und Teilnehmer protokolliert. Für alle Branchen: Werkstatt, Außendienst, Filialen.','C','2','offen'),
  ('LV4','Aufzeichnung und Zusammenfassung','Besprechungen sind nach dem Auflegen weg; wer gefehlt hat, weiß nichts.','Aufzeichnung nur wenn alle zustimmen (Hinweis und Zustimmung im Raum, Nachweis gespeichert). Abschrift und Zusammenfassung mit Beschlüssen und Aufgaben über kiFetch, Ablage am Projekt, Team oder Kurs; Videos im Hetzner-Speicher aus AK2 mit Speicherfrist. Aus bis Anwalt (Aufnahme ohne Zustimmung strafbar, Mitarbeiterdaten, AI-Act-Hinweis).','G','1','offen'),
  ('LV5','Kunden-Videotermin','Online-Buchung kennt nur Termine vor Ort; Beratung per Video läuft über fremde Links.','Terminart „Video“: Kunde bucht online und bekommt den Raum-Link in Bestätigung und Erinnerung, Gastgeber startet aus dem Kalender. Für Beratung, Angebotsbesprechung, 1:1-Coaching, Fernhilfe.','C','1','offen'),
  ('CO1','Öffentliche Anmeldung für Kurse und Veranstaltungen','Bildungskurse und Veranstaltungen haben Plätze, Warteliste und Tickets, aber Kunden können sich nicht selbst anmelden; der Betrieb trägt alles von Hand ein.','Öffentliche Anmeldeseite je Kurs und Veranstaltung (auch auf der Kunden-Website), Plätze und Warteliste live, Bestätigung per Mail, Bezahl-Link, Einwilligung nur wenn nötig.','C','1','offen'),
  ('CO2','Klientenakte für 1:1-Coaching und Beratung','Sitzungsnotizen gibt es nur in der Praxis; Ziele, Hausaufgaben und Fragebögen vor dem Erstgespräch fehlen. Pakete nur über die Mehrfachkarte, ohne Bezug zu den Sitzungen.','Klientenakte: Sitzungsnotizen (nur Coach), Ziele mit Fortschritt, Aufgaben bis zur nächsten Sitzung, Fragebogen vor dem Erstgespräch per Link (aus den vorhandenen Formularen), Paket mit Rest-Sitzungen, die bei jeder Sitzung abgebucht werden, Verlauf auf einen Blick.','C','2','offen'),
  ('CO3','Academy für Kunden: Quiz, Zertifikat, Freigabe','Die Academy ist nur für Mitarbeiter, ohne Quiz; die vorhandene Teilnahmebescheinigung wird dort nicht genutzt.','Kurse wahlweise für Kunden freigeben (nach AK1), Quiz je Lektion mit Bestehensgrenze, Zertifikat aus lib/zertifikat.ts beim Abschluss, Kursfortschritt je Teilnehmer.','C','1','offen'),
  ('CO4','Teilnehmer-Login und Mitgliederbereich','Externe bekommen nur Einmal-Links (Portal, Webinar); es gibt keinen Mitgliederbereich.','Eigener Login für Kunden und Teilnehmer, strikt getrennt von Mitarbeitern (eigene Rolle, eigene Rechte, nie Zugriff aufs Dashboard), Zwei-Faktor wahlweise. Mitgliederbereich im Look des Betriebs: Kurse, Live-Termine, Community, Rechnungen. Auth: gemeinsam, Aussperr-Risiken vorher prüfen.','G','2','offen'),
  ('CO5','Kurse und Mitgliedschaften verkaufen','Bezahlt wird nur per Link zum eigenen Anbieter, ein Zugang wird nicht freigeschaltet; keine wiederkehrende Mitgliedschaft für digitale Inhalte.','Kurs oder Mitgliedschaft als Angebot mit Preis, nach Zahlungseingang automatisch freigeschaltet, Abo monatlich/jährlich, Raten (mit VK16), Gutscheincodes. Bei Kündigung oder Rücklastschrift Zugang sperren. Aus bis Anwalt (Widerruf bei digitalen Inhalten, Verbraucherverträge).','G','2','offen'),
  ('CO6','Live-Kurse und Mitglieder-Calls','Live-Termine für Kursteilnehmer und Mitglieder laufen über Zoom-Links von Hand.','Live-Raum an Kurs oder Mitgliedschaft: alle Teilnehmer automatisch eingeladen, Kalender mit Zusage, Erinnerungen wie beim Webinar, Aufzeichnung (mit Zustimmung) landet im Kurs. Braucht LV1.','C','1','wartet auf LV1'),
  ('CO7','Webinar ausbauen','Webinare sind kostenlos, laufen nur über externe Links und nicht als Aufzeichnung weiter.','Kostenpflichtige Webinare (mit CO5), eigener Live-Raum statt Link (bis zur Raumgröße, darüber weiter Link oder Livestream), Wiederholung der Aufzeichnung zu festen Zeiten mit ehrlicher Kennzeichnung „Aufzeichnung“.','C','1','offen'),
  ('CO8','Community je Kurs oder Mitgliedschaft','Kein Austausch der Teilnehmer untereinander; der Team-Chat ist nur für Mitarbeiter.','Beitrags-Feed je Kurs oder Gruppe, Kommentare an Lektionen, Fragen an den Coach, Moderation (melden, ausblenden, sperren), Glocke bei Antworten. Aus bis Anwalt (Moderationspflichten, Nutzungsbedingungen).','C','2','offen'),
  ('CO9','Punkte, Level und Rangliste','Medaillen gibt es nur in der Mitarbeiter-Academy.','Punkte für Lektionen, Beiträge und Live-Teilnahme, Level, Rangliste (abschaltbar), Freischaltung von Inhalten ab einem Level. Baut auf den Academy-Medaillen auf.','C','1','offen'),
  ('CO10','Empfehlungs-Links mit Provision','Empfehlungsgeber werden von Hand verwaltet; Empfehlungs-Links mit Zählung fehlen.','Persönlicher Empfehlungs-Link je Partner, Zuordnung von Anmeldung und Kauf, Provision über lib/provision.ts, Partner-Übersicht im Portal. Aus bis Anwalt (Cookies und Einwilligung, Kennzeichnung als Werbung).','C','1','offen'),
])
S.append(S_CO)
S.append(("s4","Externe Partner · kurz vor dem Anwalt vorbereiten","Code so weit wie möglich (Sandbox), dazu Schritt-für-Schritt-Anleitung, was Martin beantragt",[
("E1","BANKSapi – Bankumsätze automatisch","Bankumsätze nur per Datei-Import (CSV, CAMT, MT940).","Automatischer Abruf über BANKSapi BANKS/Connect (BaFin-Lizenz liegt bei BANKSapi, Abrechnung je Nutzer), Abgleich mit offenen Rechnungen. 32 Testtage komplett nutzen (Sandbox und echte Banken), danach Starter mit 36 Monaten Laufzeit (rund 33 % Rabatt).","G","2","wartet auf Testzugang"),
("E2","Echte Kassen-TSE","Die Kasse läuft nur im Demo-Modus ohne echte TSE.","Anbindung fiskaly oder Deutsche Fiskal, Kassen-Meldung.","G","1","wartet auf Konto"),
("E3","DATEVconnect","DATEV nur als Datei-Export.","Direkte Übergabe an den Steuerberater über DATEVconnect.","C","1","wartet auf Zugang"),
("E4","Shop- und Versand-Schnittstellen","Shopware, Shopify, WooCommerce und DHL sind gebaut, aber nie mit echtem Konto getestet.","Test mit echten Konten, Fehler beheben.","C","1","wartet auf Testkonten"),
("K11b","Fahrzeugbörsen mobile.de und AutoScout24","Fahrzeuge müssen in mobile.de und AutoScout24 von Hand eingestellt werden; die eigene Börse (K11a) läuft, die großen Börsen nicht.","Hochladen und Abgleich über das Konto des Händlers (mobile.de Seller-API, AutoScout24/TruckScout24 Listing-API): Fahrzeuge, Fotos, Preisänderungen, Verkauft-Meldung; Anfragen der Börsen in „Anfragen und Suchaufträge“. Braucht Händler-Vertrag und API-Zugang.","G","1","wartet auf Händler-Zugang"),
("E5","THG-Quote für E-Fahrzeuge (Partner)","Betriebe mit E-Autos verschenken jedes Jahr die THG-Prämie, weil niemand daran denkt.","Partner-Andockstelle wie carVertical: Fahrzeugschein im eigenen Konto beim Partner einreichen, Erinnerung jedes Jahr; ARGONAUT vermittelt nur.","C","1","wartet auf Partner"),
("K19","carVertical: Bericht per Knopf (API)","Händler kaufen Historienberichte getrennt; Käufer sehen in der Börse keinen unabhängigen Nachweis zu Unfällen, Kilometerstand und Diebstahl.","Bericht-Link und Siegel sind mit Paket 274 live; jetzt über die B2B-API Bericht per FIN direkt aus der Handelsakte bzw. beim Ankauf, Abrechnung über das Konto des Händlers. Braucht Partner-Vertrag und API-Zugang; Anwalt: Weitergabe der FIN, Werbung mit Siegel.","G","1","wartet auf Partner-Vertrag"),
]))
S.append(("s5","Nach der Abnahme durch den Anwalt","Erst wenn alles rechtlich freigegeben ist",[
("AN1","Anwalt-Erstgespräch mit 30 Fragen","Die Anwaltsliste war auf 137 Fragen angewachsen; Kosten und Festpreis unklar; Termin wegen Krankheit verschoben.","Nach Bauen und Testtag: Erstgespräch (kostenlos) mit dem Dokument „ARGONAUT Anwalt Erstgespräch“ (30 Fragen, Prio A 18 vor dem ersten Kunden), Kostenschätzung und Festpreis je Paket A/B, Rahmen 2.000 € netto. Vorher: Unterlagen mit eRecht24 (Systembeschreibung, AGB, AV-Vertrag, TOMs, Datenschutzerklärung); Martin: Zwei-Faktor, AV-Verträge der Anbieter, Voyage-Widerspruch, Supabase-Region.","M","0","wartet auf Termin"),
("B11b","Branchen-Dossiers freigeben und rausgeben","385 Dossiers haben geprüften Text, rausgegeben wird aber noch keins; 206 Branchen sind bis zur Anwaltsprüfung gesperrt, 107 bewusst zurückgestellt (Liste für den Anwalt).","Nach der Freigabe: gesperrte Bereiche öffnen und Texte schreiben, zurückgestellte Branchen einzeln nachziehen, dann Dossiers ausgeben – nur Gebautes, „in Vorbereitung“ mit Begründung.","C","1","wartet auf Anwalt"),
]))
S.append(("s6","Ganz zum Schluss · Empfehlungen für die ersten Kunden","Nach dem Anwalt: welche Kunden ARGONAUT am stärksten weitertragen (Multiplikatoren)",[
("EK1","Erste Kunden nach Multiplikator-Wirkung wählen","Erste Kunden kommen zufällig; der Partner-Effekt aus K18 (Partner lernen ARGONAUT über Aufträge und Gastlinks kennen) wird nicht gezielt genutzt.","Rangliste Platz 1–13 in docs/strategie/ARGONAUT-MULTIPLIKATOR-BRANCHEN-12-10-2026.md: zuerst Hausverwaltung (ca. 140 im Kreis Böblingen, ca. 950 in Region und Nachbarkreisen, Hochrechnung), Generalunternehmer/Bauträger und Architekt – sie ziehen das Handwerk nach. Technik: Partner-Auftrag an ein allgemeines Objekt (Wohnung, Baustelle, Event, Schadensfall) statt nur ans Fahrzeug. Pflege, Praxen, Steuerberater erst nach Anwalt (R50). Keine Werbe-Mails an Partner unserer Kunden (UWG).","G","0","wartet auf Anwalt"),
]))
